/** The whole stylesheet: tokens, base and prose. */
export const css: string = "/*\n * Tempra design tokens: the one place values live (TEMPRA-8). Take 2 of the design (TEMPRA-53,\n * design/handoff/layout-take-2) set structure and type: neutral greys, a serif for concept bodies,\n * a type scale, radii and one soft shadow. Take 3 (TEMPRA-106, design/handoff/layout-take-3) set\n * the frame's sizes, squarer corners and the one colour allowed before the palette: a small warm\n * dot for an agent's recent change. Take 4 (TEMPRA-113, design/handoff/layout-take-4) set the top\n * bar, the wider sidebar and the panel, and gave the dot a second, pulsing state. The palette\n * (TEMPRA-1) changes values here and both the app and the site follow. Light and dark come from\n * the system through light-dark(), or from the account's theme on the root (data-theme).\n */\n:root {\n  color-scheme: light dark;\n\n  /* Color: surfaces */\n  --tempra-color-bg: light-dark(#ffffff, #1b1b1d); /* the page, panels, pills */\n  --tempra-color-ground: light-dark(#f3f3f1, #121214); /* the page under them, inset fills */\n  --tempra-color-hover: light-dark(#e9e9e6, #222225);\n  --tempra-color-selected: light-dark(#e1e1dd, #2a2a2e);\n  --tempra-color-selection: light-dark(#dededa, #3a3a3d);\n\n  /* Color: text, in three steps. Text people read is text or muted, at least 4.5:1 on every\n     surface in light and dark (TEMPRA-132; design/contrast.test.ts). Faint is under that: icons,\n     rules and disabled controls only, never words. */\n  --tempra-color-text: light-dark(#1a1a1b, #ececea);\n  --tempra-color-muted: light-dark(#616165, #9a9a9e);\n  --tempra-color-faint: light-dark(#a3a3a7, #68686c);\n\n  /* Color: lines */\n  --tempra-color-border: light-dark(#e8e8e4, #2a2a2d);\n  --tempra-color-border-strong: light-dark(#d2d2ce, #3c3c40);\n\n  /* Focus (TEMPRA-132): a 2px ring in the text colour on every control focused by keyboard\n     (:focus-visible), until the palette (TEMPRA-1) designs its own */\n  --tempra-focus-ring: 2px solid var(--tempra-color-text);\n  --tempra-focus-offset: 2px;\n\n  /* Color: the change dot (the only colour before the palette) */\n  --tempra-color-agent: light-dark(#e8722a, #f0884a);\n\n  /* Color: a dimmed page behind a sheet or a full-screen view */\n  --tempra-color-scrim: light-dark(rgb(20 20 22 / 0.2), rgb(0 0 0 / 0.5));\n\n  /* Color: the dark frame an attachment is shown on (take 4, board 28), and a mark on it */\n  --tempra-color-frame: light-dark(#0e0e0f, #0a0a0b);\n  --tempra-color-frame-ink: light-dark(#8a8a8e, #8a8a8e);\n\n  /* Color: links are text, underlined in running text (no colour until the palette) */\n  --tempra-color-link: var(--tempra-color-text);\n  --tempra-color-link-visited: var(--tempra-color-text);\n  --tempra-color-code-bg: var(--tempra-color-ground);\n\n  /* Elevation */\n  --tempra-shadow:\n    0 1px 2px light-dark(rgb(0 0 0 / 0.04), rgb(0 0 0 / 0.4)),\n    0 6px 24px light-dark(rgb(0 0 0 / 0.04), rgb(0 0 0 / 0.35));\n\n  /* Type (TEMPRA-108): the serif is the document; everything else is the app's sans.\n     body: all of the app and the site (chrome, view titles, the byline, comments, public pages).\n     reader: a concept's own text only (its title, description and .prose body).\n     mono: code, fences, the Markdown view, paths and hashes. */\n  --tempra-font-body:\n    -apple-system, BlinkMacSystemFont, \"SF Pro Text\", system-ui, \"Segoe UI\", Helvetica, sans-serif;\n  --tempra-font-reader:\n    \"Iowan Old Style\", \"Palatino Linotype\", Charter, Georgia, \"Times New Roman\", serif;\n  --tempra-font-mono: ui-monospace, \"SF Mono\", Menlo, monospace;\n  --tempra-font-size: 14px; /* the app's base text */\n  --tempra-measure: 680px; /* the reader's column, with its padding */\n  --tempra-measure-reader: 34em; /* concept text: about 66 characters of the reader's serif */\n\n  /* Type scale: the only pixel sizes in the CSS (inside .prose, sizes are em of the reading size) */\n  --tempra-text-initial: 9px; /* an avatar's initials */\n  --tempra-text-label: 11px; /* uppercase labels, marks */\n  --tempra-text-meta: 12px; /* timestamps, crumbs, small print */\n  --tempra-text-ui: 13px; /* controls, panels, the tree, comments */\n  --tempra-text-name: 15px; /* a library's name, dialog heads, the wordmark */\n  --tempra-text-reader: 17px; /* a concept's body and description, the landing page's lede */\n  --tempra-text-h2: 22px; /* an attachment's name */\n  --tempra-text-page: 28px; /* a view's title (h1); a concept's title on a phone */\n  --tempra-text-title: 36px; /* a concept's title */\n\n  /* Weights: three */\n  --tempra-weight-regular: 400; /* text */\n  --tempra-weight-medium: 500; /* names in rows, a concept's title, the body's h1 and h2 */\n  --tempra-weight-strong: 600; /* the sans's headings, section labels, the wordmark */\n\n  /* Leading: three */\n  --tempra-leading-tight: 1.2; /* titles and headings */\n  --tempra-line-height: 1.5; /* the app's text */\n  --tempra-leading-reader: 1.65; /* reading */\n\n  /* Space */\n  --tempra-space-1: 0.25rem;\n  --tempra-space-2: 0.5rem;\n  --tempra-space-3: 1rem;\n  --tempra-space-4: 2rem;\n  --tempra-gutter: 8px; /* the frame's gutter */\n  --tempra-page-pad: 40px; /* a page's side padding in its column */\n\n  /* The frame (take 4): a top bar across the window, the sidebar, one panel beside a concept.\n     The breakpoints are 1100px (the panel overlays the page) and 900px (the phone layout); a\n     media query cannot read a token, so they are written where they are used. */\n  --tempra-topbar: 60px; /* the top bar */\n  --tempra-sidebar: 264px; /* the sidebar's width */\n  --tempra-panel: 360px; /* a concept's panel (Comments, History, Properties) */\n  --tempra-bar: 52px; /* the phone's top bar */\n  --tempra-drawer: min(82vw, 360px); /* the phone's drawer: about four fifths of the screen */\n  --tempra-sheet: 67dvh; /* a panel as the phone's bottom sheet: about two thirds of the screen */\n  --tempra-row: 30px; /* a sidebar row */\n  --tempra-touch: 44px; /* the least touch target on a phone */\n  --tempra-avatar: 22px;\n  --tempra-avatar-small: 20px;\n  --tempra-dot: 6px; /* an agent's change, a reader's unverified state */\n\n  /* A concept's columns (take 4): the text, centred; on the right its contents, or a panel */\n  --tempra-column-text: 620px;\n  --tempra-contents: 200px;\n  --tempra-page-width: 760px; /* home, Activity, a folder, the Inbox */\n\n  /* Shape: squarer than take 2 */\n  --tempra-radius: 5px; /* code */\n  --tempra-radius-mark: 3px;\n  --tempra-radius-row: 7px; /* sidebar rows, inputs */\n  --tempra-radius-box: 10px; /* cards, list boxes, threads */\n  --tempra-radius-card: 10px; /* the public pages' sheet, dialogs */\n  --tempra-radius-tile: 6px; /* the library's initial */\n  --tempra-radius-pill: 999px;\n\n  /* Motion: the pulse of the change dot while an agent writes */\n  --tempra-pulse: 1.6s;\n}\n\n/* The account's theme (take 4): the shell puts it on the root; the tokens above follow. */\n:root[data-theme=\"light\"] {\n  color-scheme: light;\n}\n\n:root[data-theme=\"dark\"] {\n  color-scheme: dark;\n}\n\n/* Element defaults for every page of the app and the site; values come from tokens.css. */\n*,\n*::before,\n*::after {\n  box-sizing: border-box;\n}\n\nbody {\n  margin: 0;\n  padding: var(--tempra-space-3);\n  background: var(--tempra-color-bg);\n  color: var(--tempra-color-text);\n  font-family: var(--tempra-font-body);\n  font-size: var(--tempra-font-size);\n  line-height: var(--tempra-line-height);\n  -webkit-font-smoothing: antialiased;\n}\n\n::selection {\n  background: var(--tempra-color-selection);\n}\n\nh1 {\n  margin: 0 0 var(--tempra-space-3);\n  font-size: var(--tempra-text-page);\n  font-weight: var(--tempra-weight-medium);\n  line-height: var(--tempra-leading-tight);\n  letter-spacing: -0.02em;\n}\n\nh2 {\n  margin: var(--tempra-space-4) 0 var(--tempra-space-2);\n  font-size: var(--tempra-font-size);\n  font-weight: var(--tempra-weight-strong);\n}\n\nh3 {\n  font-size: var(--tempra-text-ui);\n  font-weight: var(--tempra-weight-strong);\n}\n\na {\n  color: var(--tempra-color-link);\n  text-decoration: underline;\n  text-decoration-color: var(--tempra-color-border-strong);\n  text-underline-offset: 2px;\n}\n\na:visited {\n  color: var(--tempra-color-link-visited);\n}\n\na:hover {\n  text-decoration-color: currentcolor;\n}\n\n/* Focus (TEMPRA-132): the ring, 2px in the text colour, on every control reached by keyboard. */\n:focus-visible {\n  outline: var(--tempra-focus-ring);\n  outline-offset: var(--tempra-focus-offset);\n}\n\n/* A text field has the same ring, close to its edge. */\ninput:not([type=\"checkbox\"], [type=\"radio\"], [type=\"file\"]):focus-visible,\nselect:focus-visible,\ntextarea:focus-visible {\n  outline: var(--tempra-focus-ring);\n  outline-offset: 1px;\n}\n\ncode,\npre,\nkbd,\nsamp {\n  font-family: var(--tempra-font-mono);\n}\n\ncode {\n  font-size: 0.92em;\n}\n\n/* A block of code or a command never widens the page: it scrolls on its own. */\npre {\n  max-width: 100%;\n  overflow-x: auto;\n}\n\nkbd {\n  padding: 1px 7px;\n  border-radius: var(--tempra-radius-pill);\n  background: var(--tempra-color-ground);\n  color: var(--tempra-color-muted);\n  font-family: inherit;\n  font-size: var(--tempra-text-label);\n}\n\nhr {\n  border: 0;\n  border-top: 1px solid var(--tempra-color-border);\n}\n\n/* Controls: pills. A plain button is outlined; .primary is the one solid action; .ghost is text.\n   A link that acts as a button (Review, Back to current) takes .button and looks the same. */\nbutton,\ninput,\nselect,\ntextarea {\n  font: inherit;\n  color: inherit;\n}\n\nbutton,\na.button {\n  padding: 5px 12px;\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-pill);\n  background: var(--tempra-color-bg);\n  font-size: var(--tempra-text-ui);\n  white-space: nowrap;\n  cursor: pointer;\n}\n\na.button {\n  display: inline-block;\n  color: var(--tempra-color-text);\n  line-height: var(--tempra-line-height);\n  text-decoration: none;\n}\n\nbutton:hover:not(:disabled),\na.button:hover {\n  background: var(--tempra-color-hover);\n  color: var(--tempra-color-text);\n}\n\nbutton:disabled {\n  cursor: default;\n  opacity: 0.5;\n}\n\nbutton.primary,\na.button.primary {\n  border-color: var(--tempra-color-text);\n  background: var(--tempra-color-text);\n  color: var(--tempra-color-bg);\n  font-weight: var(--tempra-weight-medium);\n}\n\nbutton.primary:hover:not(:disabled),\na.button.primary:hover {\n  background: var(--tempra-color-text);\n  opacity: 0.85;\n}\n\n/* A text-only button: a link's look, a button's job. */\nbutton.ghost {\n  border-color: transparent;\n  background: transparent;\n  color: var(--tempra-color-muted);\n}\n\ninput:not([type=\"checkbox\"], [type=\"radio\"], [type=\"file\"]),\nselect,\ntextarea {\n  max-width: 100%;\n  padding: 5px 10px;\n  border: 1px solid var(--tempra-color-border-strong);\n  border-radius: var(--tempra-radius-row);\n  background: var(--tempra-color-bg);\n  font-size: var(--tempra-text-ui);\n}\n\ntextarea {\n  line-height: var(--tempra-line-height);\n}\n\nfieldset {\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-box);\n}\n\n/* A form as a column: a label over each field, choices on their own lines, actions last. */\nform.stack fieldset {\n  margin: 0 0 20px;\n  padding: 0;\n  border: 0;\n}\n\nform.stack legend {\n  margin-bottom: 6px;\n  padding: 0;\n  font-weight: var(--tempra-weight-medium);\n}\n\n.field {\n  display: block;\n  margin: 10px 0;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-ui);\n}\n\n.field input,\n.field select {\n  display: block;\n  width: 100%;\n  max-width: 22rem;\n  margin-top: 4px;\n  color: var(--tempra-color-text);\n  font-size: var(--tempra-font-size);\n}\n\n.choice {\n  display: flex;\n  align-items: baseline;\n  gap: 8px;\n  margin: 4px 0;\n}\n\n.indent {\n  margin: 2px 0 6px 24px;\n}\n\n.actions {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n  margin-top: 8px;\n}\n\ntable {\n  border-collapse: collapse;\n}\n\nth,\ntd {\n  padding: var(--tempra-space-1) var(--tempra-space-2);\n  text-align: left;\n  vertical-align: top;\n}\n\nimg {\n  max-width: 100%;\n}\n\ndetails > summary {\n  cursor: pointer;\n}\n\n/* Text roles used across pages. */\n.muted {\n  color: var(--tempra-color-muted);\n}\n\n/* Faint is for icons and separators, never words (under 4.5:1; TEMPRA-132). */\n.faint {\n  color: var(--tempra-color-faint);\n}\n\n::placeholder {\n  color: var(--tempra-color-muted);\n  opacity: 1;\n}\n\n/* Who acted (AgentName, TEMPRA-131): the name, then whom an agent acts for, quieter. */\n.agent-name > b {\n  color: var(--tempra-color-text);\n  font-weight: var(--tempra-weight-medium);\n}\n\n.agent-for {\n  color: var(--tempra-color-muted);\n}\n\n.small {\n  font-size: var(--tempra-text-meta);\n}\n\n/* A form field's hint under it: what it becomes and the format it takes. */\n.field-hint {\n  display: block;\n  margin-top: var(--tempra-space-1);\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-meta);\n}\n\n.warn {\n  font-weight: var(--tempra-weight-medium);\n}\n\n/* An uppercase label over a group (SOURCES, LINKED FROM). */\n.label {\n  margin: 0 0 var(--tempra-space-2);\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-label);\n  font-weight: var(--tempra-weight-regular);\n  letter-spacing: 0.04em;\n  text-transform: uppercase;\n}\n\n/* A message about the page (saved, an error, a version in the past). */\n.notice {\n  margin: var(--tempra-space-2) 0;\n  padding: 10px 12px;\n  border-radius: var(--tempra-radius-box);\n  background: var(--tempra-color-ground);\n  font-size: var(--tempra-text-ui);\n}\n\n.chip {\n  display: inline-block;\n  padding: 1px 7px;\n  border: 1px solid transparent;\n  border-radius: var(--tempra-radius-pill);\n  background: var(--tempra-color-ground);\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-label);\n  white-space: nowrap;\n}\n\n/* Something to act on: in the text colour (no colour until the palette). */\n.chip.warn,\n.chip.bad {\n  color: var(--tempra-color-text);\n}\n\n/* Text for screen readers only: what a symbol (a mark, an icon) means. */\n.visually-hidden {\n  position: absolute;\n  width: 1px;\n  height: 1px;\n  overflow: hidden;\n  clip-path: inset(50%);\n  white-space: nowrap;\n}\n\n/*\n * How a rendered concept reads (tempra-dev: app/reader, Reading typography): the body of a\n * concept, in the app now and wherever concepts are shown later (the site, inline MCP Apps views).\n * Scoped to .prose. A serif at 17px, about 66 characters to the line, spacing in em so the rhythm\n * scales with the text. Greys, type, spacing and rules only until the palette (TEMPRA-1).\n */\n.prose {\n  max-width: var(--tempra-measure-reader);\n  color: var(--tempra-color-text);\n  font-family: var(--tempra-font-reader);\n  font-size: var(--tempra-text-reader);\n  line-height: var(--tempra-leading-reader);\n  font-kerning: normal;\n  font-optical-sizing: auto;\n  font-variant-ligatures: common-ligatures;\n  /* Figures that sit in running text; tables and markers switch to lining, tabular ones. */\n  font-variant-numeric: oldstyle-nums proportional-nums;\n  /* Quotes and stops hang into the margin where the browser can (Safari). */\n  hanging-punctuation: first allow-end;\n  /* A long URL or identifier wraps rather than pushing the column wider; words never break. */\n  overflow-wrap: break-word;\n  hyphens: manual;\n  text-size-adjust: 100%;\n}\n\n.prose > :first-child,\n.prose > [hidden]:first-child + * {\n  margin-top: 0;\n}\n\n.prose > :last-child {\n  margin-bottom: 0;\n}\n\n/* Vertical rhythm: one step between blocks, in em. */\n.prose p,\n.prose ul,\n.prose ol,\n.prose blockquote,\n.prose pre,\n.prose .table {\n  margin: 0 0 1.1em;\n}\n\n/* No line ends on a lone short word; headings are balanced across their lines. */\n.prose p,\n.prose li,\n.prose blockquote {\n  text-wrap: pretty;\n}\n\n.prose strong {\n  font-weight: var(--tempra-weight-strong);\n}\n\n.prose s {\n  color: var(--tempra-color-muted);\n}\n\n/* Headings: more space above than below, so each sits with what it introduces. */\n.prose h1,\n.prose h2,\n.prose h3,\n.prose h4,\n.prose h5,\n.prose h6 {\n  margin: 1.9em 0 0.5em;\n  font-family: var(--tempra-font-reader);\n  font-variant-numeric: lining-nums proportional-nums;\n  line-height: var(--tempra-leading-tight);\n  letter-spacing: -0.005em;\n  text-wrap: balance;\n  break-after: avoid;\n  /* Clear of the cluster when a contents link scrolls to it. */\n  scroll-margin-top: 72px;\n}\n\n.prose h1 {\n  font-size: 1.65em;\n  font-weight: var(--tempra-weight-medium);\n  letter-spacing: -0.012em;\n}\n\n.prose h2 {\n  font-size: 1.35em;\n  font-weight: var(--tempra-weight-medium);\n  letter-spacing: -0.01em;\n}\n\n.prose h3 {\n  font-size: 1.12em;\n  font-weight: var(--tempra-weight-strong);\n}\n\n.prose h4,\n.prose h5,\n.prose h6 {\n  margin-top: 1.6em;\n  font-size: 1em;\n  font-weight: var(--tempra-weight-strong);\n  font-variant-caps: all-small-caps;\n  letter-spacing: 0.04em;\n}\n\n.prose h5,\n.prose h6 {\n  color: var(--tempra-color-muted);\n}\n\n/* A heading straight after another needs less room. */\n.prose :is(h1, h2, h3, h4, h5, h6) + :is(h2, h3, h4, h5, h6) {\n  margin-top: 0.7em;\n}\n\n/* Links: text-coloured, a thin underline at partial strength that firms up on hover. */\n.prose a {\n  color: inherit;\n  text-decoration-line: underline;\n  text-decoration-thickness: 1px;\n  text-decoration-color: color-mix(in srgb, currentColor 38%, transparent);\n  text-underline-offset: 0.18em;\n  text-decoration-skip-ink: auto;\n}\n\n.prose a:hover {\n  text-decoration-color: currentColor;\n}\n\n/* A link the reader would not follow (an unsafe scheme) reads as text. */\n.prose a:not([href]) {\n  text-decoration: none;\n}\n\n.prose a.broken {\n  color: var(--tempra-color-muted);\n  text-decoration-line: line-through;\n  text-decoration-color: currentColor;\n}\n\n/* Lists: muted markers, figures that line up; tight lists close, loose ones like paragraphs. */\n.prose ul,\n.prose ol {\n  padding-left: 1.4em;\n}\n\n.prose li {\n  margin: 0.2em 0;\n}\n\n.prose li::marker {\n  color: var(--tempra-color-muted);\n  font-variant-numeric: lining-nums tabular-nums;\n}\n\n.prose li > p {\n  margin: 0;\n}\n\n.prose li > :is(ul, ol) {\n  margin: 0.2em 0 0;\n}\n\n.prose :is(ul, ol).loose > li {\n  margin: 0.55em 0;\n}\n\n.prose :is(ul, ol).loose > li > p + * {\n  margin-top: 0.55em;\n}\n\n.prose .tasks {\n  padding-left: 0.1em;\n  list-style: none;\n}\n\n.prose li.task {\n  display: grid;\n  grid-template-columns: auto 1fr;\n  column-gap: 0.55em;\n  align-items: baseline;\n}\n\n.prose li.task > :not(input) {\n  grid-column: 2;\n}\n\n.prose li.task > input {\n  margin: 0;\n  accent-color: var(--tempra-color-text);\n}\n\n/* Blockquotes upright: long italic passages read slowly. */\n.prose blockquote {\n  margin-left: 0;\n  margin-right: 0;\n  padding: 0 0 0 1.1em;\n  border-left: 2px solid var(--tempra-color-border-strong);\n  color: var(--tempra-color-muted);\n}\n\n.prose blockquote > :last-child {\n  margin-bottom: 0;\n}\n\n/* Code: the mono a step down, no ligatures; inline on the code grey, blocks scroll sideways. */\n.prose code {\n  padding: 0.1em 0.35em;\n  border-radius: var(--tempra-radius);\n  background: var(--tempra-color-code-bg);\n  font-family: var(--tempra-font-mono);\n  font-size: 0.86em;\n  font-variant-ligatures: none;\n  font-variant-numeric: normal;\n  box-decoration-break: clone;\n  -webkit-box-decoration-break: clone;\n}\n\n.prose pre {\n  position: relative;\n  overflow-x: auto;\n  overscroll-behavior-x: contain;\n  padding: 14px 18px;\n  border-radius: var(--tempra-radius-row);\n  background: var(--tempra-color-code-bg);\n  font-family: var(--tempra-font-mono);\n  font-size: 0.8em;\n  font-variant-ligatures: none;\n  line-height: var(--tempra-line-height);\n  tab-size: 2;\n  white-space: pre;\n  overflow-wrap: normal;\n}\n\n.prose pre code {\n  padding: 0;\n  border-radius: 0;\n  background: none;\n  font-size: inherit;\n}\n\n/* The fence's language, quietly above the code (generated content: not part of the text). */\n.prose pre[data-lang] {\n  padding-top: 32px;\n}\n\n.prose pre[data-lang]::before {\n  content: attr(data-lang);\n  position: absolute;\n  top: 10px;\n  left: 18px;\n  color: var(--tempra-color-muted);\n  font-family: var(--tempra-font-body);\n  font-size: var(--tempra-text-label);\n  letter-spacing: 0.04em;\n  text-transform: lowercase;\n}\n\n/* What the reader shows as its markdown (raw HTML, reference links): quieter than code. */\n.prose pre.raw,\n.prose code.raw {\n  color: var(--tempra-color-muted);\n}\n\n/*\n * Tables: real tables in their own scroll container, so a wide one scrolls sideways (on a phone\n * too) instead of breaking words. A table fills the column in a hairline box, with a light header\n * row on the ground grey and rules between rows, none between columns (take 3, Figures).\n */\n.prose .table {\n  max-width: 100%;\n  overflow-x: auto;\n  overscroll-behavior-x: contain;\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-box);\n}\n\n.prose table {\n  width: 100%;\n  border-collapse: collapse;\n  font-family: var(--tempra-font-body);\n  font-size: 0.82em;\n  font-variant-numeric: lining-nums tabular-nums;\n  line-height: var(--tempra-line-height);\n}\n\n.prose th,\n.prose td {\n  padding: 0.6em 0.9em;\n  border: 0;\n  border-bottom: 1px solid var(--tempra-color-border);\n  text-align: left;\n  vertical-align: top;\n  overflow-wrap: normal;\n  word-break: normal;\n  text-wrap: pretty;\n}\n\n.prose tbody tr:last-child td {\n  border-bottom: 0;\n}\n\n.prose th {\n  background: var(--tempra-color-ground);\n  font-weight: var(--tempra-weight-medium);\n  vertical-align: bottom;\n}\n\n.prose td code,\n.prose th code {\n  background: none;\n  padding: 0;\n}\n\n.prose [data-align=\"center\"] {\n  text-align: center;\n}\n\n.prose [data-align=\"right\"] {\n  text-align: right;\n}\n\n.prose hr {\n  margin: 2.2em 0;\n  border: 0;\n  border-top: 1px solid var(--tempra-color-border);\n}\n\n/* An image in running text stays in the line, no taller than the column is wide. */\n.prose img {\n  max-width: 100%;\n  height: auto;\n  vertical-align: middle;\n}\n\n.prose .image-dropped,\n.prose .image-broken {\n  color: var(--tempra-color-muted);\n  font-style: italic;\n}\n\n.prose .image-broken {\n  padding: 0 0.3em;\n  border: 1px dashed var(--tempra-color-border-strong);\n  border-radius: var(--tempra-radius);\n}\n\n/*\n * Figures (take 3, Figures): an image alone in its paragraph, or a diagram, with a caption\n * beneath: \"Figure n.\" a step darker, then the image's title or alt text, in the UI face.\n */\n.prose figure {\n  margin: 1.6em 0;\n}\n\n.prose figure.figure > p {\n  margin: 0;\n}\n\n.prose .figure-media {\n  display: block;\n}\n\n.prose .figure-media img {\n  display: block;\n  max-width: 100%;\n  height: auto;\n  border-radius: var(--tempra-radius-box);\n}\n\n/* The image is the button that enlarges it: no button look, a focus ring when reached by keys. */\n.prose .figure-open {\n  display: block;\n  max-width: 100%;\n  padding: 0;\n  border: 0;\n  border-radius: var(--tempra-radius-box);\n  background: none;\n  cursor: zoom-in;\n}\n\n.prose .figure-open:hover:not(:disabled) {\n  background: none;\n}\n\n.prose .figure-open:focus-visible {\n  outline: var(--tempra-focus-ring);\n  outline-offset: 3px;\n}\n\n.prose figcaption {\n  margin-top: 8px;\n  color: var(--tempra-color-muted);\n  font-family: var(--tempra-font-body);\n  font-size: var(--tempra-text-meta);\n  line-height: var(--tempra-line-height);\n  text-wrap: pretty;\n  user-select: none;\n}\n\n.prose .figure-number {\n  color: var(--tempra-color-text);\n  font-weight: var(--tempra-weight-medium);\n}\n\n/* An image that can't be shown: a dashed box where it would be, saying so, its path and alt. */\n.figure-broken {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  gap: 4px;\n  min-height: 12rem;\n  padding: 24px;\n  border: 1px dashed var(--tempra-color-border-strong);\n  border-radius: var(--tempra-radius-box);\n  background: var(--tempra-color-ground);\n  color: var(--tempra-color-muted);\n  font-family: var(--tempra-font-body);\n  font-size: var(--tempra-text-meta);\n  font-style: normal;\n  line-height: var(--tempra-line-height);\n  text-align: center;\n  overflow-wrap: anywhere;\n}\n\n.figure-broken svg {\n  margin-bottom: 4px;\n  color: var(--tempra-color-faint);\n}\n\n.figure-broken .figure-broken-title {\n  color: var(--tempra-color-text);\n  font-size: var(--tempra-text-ui);\n}\n\n/* Footnote markers: a source's number, small and muted, joined to its word. */\n.prose sup.fnref {\n  margin-left: 0.08em;\n  color: var(--tempra-color-muted);\n  font-size: 0.68em;\n  font-variant-numeric: lining-nums tabular-nums;\n  line-height: 0;\n  vertical-align: super;\n  white-space: nowrap;\n}\n\n.prose sup.fnref a {\n  padding: 0 0.12em;\n  color: inherit;\n  text-decoration: none;\n}\n\n.prose sup.fnref a:hover {\n  text-decoration: underline;\n}\n\n/* Changes in the text (review mode, a version chosen in History): insertions underlined on a\n   grey ground, deletions struck through in grey; the changed block's rule is concept.css's. */\n.prose ins.diff-added {\n  background: var(--tempra-color-ground);\n  text-decoration: underline;\n  text-decoration-thickness: 1px;\n  text-underline-offset: 0.22em;\n}\n\n.prose del.diff-removed {\n  color: var(--tempra-color-muted);\n  text-decoration: line-through;\n}\n\n/*\n * What sits around a concept body in the reader (tempra-dev: app/reader): the hover cards and the\n * selection toolbar (popovers in the top layer, placed by the app through --float-x and\n * --float-y), comment highlights (the CSS Custom Highlight API), the threads in the Comments\n * panel and the stored Markdown view. Lines and greys only (no colour until TEMPRA-1).\n */\n\n/* A popover: placed at the coordinates the app gives it, never where the browser centres one. */\n.floating {\n  position: fixed;\n  inset: auto;\n  top: var(--float-y, 0);\n  left: var(--float-x, 0);\n  margin: 0;\n  padding: 0;\n  border: 0;\n  background: none;\n  color: inherit;\n  overflow: visible;\n}\n\n/* Hover cards over footnote markers and links. */\n.tooltip {\n  max-width: 22rem;\n  padding: 8px 12px;\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-box);\n  background: var(--tempra-color-bg);\n  box-shadow: var(--tempra-shadow);\n  color: var(--tempra-color-text);\n  font-family: var(--tempra-font-body);\n  font-size: var(--tempra-text-ui);\n  line-height: var(--tempra-line-height);\n  text-wrap: pretty;\n}\n\n.tooltip p {\n  margin: 0;\n}\n\n.tooltip p + p {\n  margin-top: 0.4em;\n}\n\n/*\n * Comments (TEMPRA-13). A thread's quote is underlined in the body (dotted); the one whose thread\n * is open in the Comments panel is filled grey and underlined solid; a comment being written\n * fills its text with the selection grey. Drawn as\n * highlights, so the body's DOM never changes for them.\n */\n::highlight(tempra-comment) {\n  text-decoration-line: underline;\n  text-decoration-style: dotted;\n  text-decoration-thickness: 1px;\n  text-underline-offset: 0.22em;\n}\n\n::highlight(tempra-comment-active) {\n  background-color: var(--tempra-color-hover);\n  text-decoration-line: underline;\n  text-decoration-style: solid;\n  text-decoration-thickness: 1px;\n  text-underline-offset: 0.22em;\n}\n\n::highlight(tempra-comment-draft) {\n  background-color: var(--tempra-color-selected);\n}\n\n/* The selection toolbar: a pill above the selected text. */\n.selection-tools > div {\n  display: flex;\n  gap: 2px;\n  padding: 3px;\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-pill);\n  background: var(--tempra-color-bg);\n  box-shadow: var(--tempra-shadow);\n  font-family: var(--tempra-font-body);\n}\n\n.selection-tools button {\n  padding: 4px 12px;\n  border: 0;\n  background: var(--tempra-color-text);\n  color: var(--tempra-color-bg);\n  font-size: var(--tempra-text-meta);\n  font-weight: var(--tempra-weight-medium);\n}\n\n.selection-tools button:hover:not(:disabled) {\n  background: var(--tempra-color-text);\n  opacity: 0.85;\n}\n\n/* A footnote's own text in the Sources section and a marker's card. */\n.note > p {\n  margin: 0;\n}\n\n.note > p + * {\n  margin-top: 0.4em;\n}\n\n/*\n * Diagrams (tempra-dev: app/diagrams): Pele's SVG themed through its custom properties, greys only\n * until the palette (TEMPRA-1), so dark mode follows the tokens. Colours an author sets in the\n * diagram are content and stay. In the body it sits in a quiet frame (take 3, Figures) with Source\n * and Enlarge in its corner, and scrolls sideways when it cannot shrink to the column; the\n * full-screen view draws it again with the same theme.\n */\n.prose figure.diagram,\n.lightbox {\n  --pele-bg: var(--tempra-color-bg);\n  --pele-fg: var(--tempra-color-text);\n  --pele-muted: var(--tempra-color-muted);\n  --pele-line: var(--tempra-color-muted);\n  --pele-surface: var(--tempra-color-ground);\n  --pele-surface-alt: var(--tempra-color-hover);\n  --pele-border: var(--tempra-color-border-strong);\n  --pele-accent: var(--tempra-color-text);\n  --pele-font: var(--tempra-font-body);\n  --pele-font-mono: var(--tempra-font-mono);\n  --pele-radius: var(--tempra-radius-row);\n  --pele-series-1: var(--tempra-color-text);\n  --pele-series-2: var(--tempra-color-muted);\n  --pele-series-3: var(--tempra-color-faint);\n  --pele-series-4: var(--tempra-color-border-strong);\n  --pele-series-5: var(--tempra-color-selection);\n  --pele-series-6: var(--tempra-color-selected);\n  --pele-series-7: var(--tempra-color-hover);\n  --pele-series-8: var(--tempra-color-ground);\n}\n\n.prose figure.diagram {\n  margin: 1.6em 0;\n}\n\n.prose .diagram-frame {\n  position: relative;\n  padding: 40px 20px 20px;\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-box);\n}\n\n.prose .diagram-svg {\n  overflow-x: auto;\n  overscroll-behavior-x: contain;\n  font-family: var(--tempra-font-body);\n  font-size: var(--tempra-text-ui);\n}\n\n.prose .diagram-svg svg {\n  display: block;\n  max-width: 100%;\n  height: auto;\n  margin: 0 auto;\n}\n\n.prose .diagram-frame pre.diagram-source {\n  margin: 0;\n}\n\n/* Source and Enlarge: small grey pills in the frame's corner. */\n.prose .figure-tools {\n  position: absolute;\n  top: 8px;\n  right: 8px;\n  display: flex;\n  gap: 2px;\n  font-family: var(--tempra-font-body);\n}\n\n.prose .figure-tools button {\n  display: inline-grid;\n  place-items: center;\n  min-width: 24px;\n  height: 24px;\n  padding: 0 10px;\n  border: 0;\n  background: var(--tempra-color-ground);\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-label);\n  line-height: 1;\n}\n\n.prose .figure-tools button:hover:not(:disabled),\n.prose .figure-tools button[aria-pressed=\"true\"] {\n  background: var(--tempra-color-hover);\n  color: var(--tempra-color-text);\n}\n\n.prose .figure-tools .figure-enlarge {\n  padding: 0;\n}\n\n.prose figure.diagram.failed pre {\n  margin: 0;\n}\n\n.prose .diagram-notice {\n  margin: 6px 0 0;\n  color: var(--tempra-color-muted);\n  font-family: var(--tempra-font-body);\n  font-size: var(--tempra-text-meta);\n}\n\n/* On a touch screen the corner controls are full-size targets. */\n@media (pointer: coarse) {\n  .prose .diagram-frame {\n    padding-top: 60px;\n  }\n\n  .prose .figure-tools {\n    top: 6px;\n    right: 6px;\n  }\n\n  .prose .figure-tools button {\n    min-width: var(--tempra-touch);\n    height: var(--tempra-touch);\n    font-size: var(--tempra-text-meta);\n  }\n}\n\n/*\n * The full-screen view of a figure (take 3, Lightbox): a modal dialog over the app on the ground\n * colour. A header (where, \"Figure n of m\", Open original and Download as pills, close), the\n * figure as large as fits between previous and next, and beneath it the caption and a quiet line.\n */\n.lightbox {\n  position: fixed;\n  inset: 0;\n  width: 100%;\n  max-width: none;\n  height: 100%;\n  max-height: none;\n  margin: 0;\n  padding: 0;\n  border: 0;\n  background: var(--tempra-color-ground);\n  color: var(--tempra-color-text);\n  font-family: var(--tempra-font-body);\n  font-size: var(--tempra-text-ui);\n  line-height: var(--tempra-line-height);\n  overflow: hidden;\n}\n\n.lightbox[open] {\n  display: grid;\n  grid-template-rows: auto minmax(0, 1fr) auto;\n}\n\n.lightbox::backdrop {\n  background: var(--tempra-color-ground);\n}\n\n.lightbox-head {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 8px 12px;\n  padding: 16px 20px;\n}\n\n.lightbox-where {\n  color: var(--tempra-color-muted);\n}\n\n.lightbox-where::after {\n  content: \"·\";\n  margin-left: 12px;\n  color: var(--tempra-color-faint);\n}\n\n.lightbox-actions {\n  display: flex;\n  gap: 6px;\n  margin-left: auto;\n}\n\n.lightbox-actions a {\n  display: inline-flex;\n  align-items: center;\n  padding: 6px 14px;\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-pill);\n  background: var(--tempra-color-bg);\n  color: var(--tempra-color-text);\n  text-decoration: none;\n  white-space: nowrap;\n}\n\n.lightbox-actions a:hover {\n  background: var(--tempra-color-hover);\n}\n\n.lightbox-round {\n  display: inline-grid;\n  flex: none;\n  place-items: center;\n  width: 34px;\n  height: 34px;\n  padding: 0;\n  border: 1px solid var(--tempra-color-border);\n  background: var(--tempra-color-bg);\n}\n\n.lightbox-stage {\n  display: grid;\n  grid-template-columns: auto minmax(0, 1fr) auto;\n  align-items: center;\n  gap: 16px;\n  min-height: 0;\n  padding: 0 20px;\n}\n\n.lightbox-stage .lightbox-prev,\n.lightbox-stage .lightbox-next {\n  width: var(--tempra-touch);\n  height: var(--tempra-touch);\n}\n\n.lightbox-prev {\n  grid-column: 1;\n}\n\n.lightbox-figure {\n  display: grid;\n  grid-column: 2;\n  place-items: center;\n  width: 100%;\n  height: 100%;\n  min-height: 0;\n}\n\n.lightbox-next {\n  grid-column: 3;\n}\n\n.lightbox-figure > img {\n  display: block;\n  max-width: 100%;\n  max-height: 100%;\n  object-fit: contain;\n  border-radius: var(--tempra-radius-card);\n  box-shadow: var(--tempra-shadow);\n}\n\n.lightbox-figure > .figure-broken {\n  width: min(100%, 32rem);\n}\n\n.lightbox-diagram {\n  box-sizing: border-box;\n  width: 100%;\n  height: 100%;\n  padding: 24px;\n  border-radius: var(--tempra-radius-card);\n  background: var(--tempra-color-bg);\n  box-shadow: var(--tempra-shadow);\n  font-size: var(--tempra-text-ui);\n}\n\n.lightbox-diagram svg {\n  display: block;\n  width: 100%;\n  height: 100%;\n}\n\n.lightbox-source {\n  max-width: 100%;\n  max-height: 100%;\n  margin: 0;\n  padding: 16px 18px;\n  overflow: auto;\n  border-radius: var(--tempra-radius-box);\n  background: var(--tempra-color-bg);\n  font-family: var(--tempra-font-mono);\n  font-size: var(--tempra-text-ui);\n}\n\n.lightbox-foot {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 4px;\n  padding: 18px 20px 26px;\n  text-align: center;\n}\n\n.lightbox-caption {\n  max-width: var(--tempra-measure);\n  margin: 0;\n  font-size: var(--tempra-text-name);\n  text-wrap: pretty;\n}\n\n.lightbox-facts {\n  max-width: var(--tempra-measure);\n  margin: 0;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-meta);\n  overflow-wrap: anywhere;\n}\n\n.lightbox-facts > span + span::before {\n  content: \" · \";\n}\n\n/* A phone: smaller gutters, 44px targets, no keyboard hint. */\n@media (max-width: 600px) {\n  .lightbox-head {\n    padding: 8px 12px;\n  }\n\n  .lightbox-where {\n    display: none;\n  }\n\n  .lightbox-actions a {\n    min-height: var(--tempra-touch);\n    padding: 0 14px;\n  }\n\n  .lightbox-round {\n    width: var(--tempra-touch);\n    height: var(--tempra-touch);\n  }\n\n  .lightbox-stage {\n    gap: 4px;\n    padding: 0 4px;\n  }\n\n  .lightbox-foot {\n    padding: 12px 16px 20px;\n  }\n\n  .lightbox-hint {\n    display: none;\n  }\n}\n\n/*\n * The app's frame (TEMPRA-19; take 2 in TEMPRA-53, take 3 in TEMPRA-106, take 4 in TEMPRA-113;\n * tempra-dev: app/workspace). A docs-site layout: a top bar across the window, split at the\n * sidebar's edge (the mark, the library switcher and search over the sidebar; the crumbs, the\n * page's tools, the bell and the avatar over the page), a navigation sidebar with a hairline on\n * its right, and the page as a flat column: no ground, no sheet. The sidebar can be hidden; under\n * 900px it is a drawer behind a top bar. Library settings and the account's pages use the same\n * frame with a sidebar of their own. A concept's own layout is in concept.css; the person's views\n * (home, Activity, a folder) in views.css.\n */\nbody:has(> #root),\nbody.ground {\n  padding: 0;\n  background: var(--tempra-color-bg);\n}\n\n/* ---------- Shared pieces: menus, the avatar, icon buttons ---------- */\n\n/* A menu: a button that opens a card of links below it. */\n.menu {\n  position: relative;\n}\n\n.menu-button {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  padding: 4px 8px;\n  border: 0;\n  background: transparent;\n  color: var(--tempra-color-muted);\n}\n\n.menu-button .caret {\n  display: inline-flex;\n  color: var(--tempra-color-faint);\n}\n\n.menu-list {\n  position: absolute;\n  top: calc(100% + 6px);\n  z-index: 20;\n  display: flex;\n  flex-direction: column;\n  gap: 1px;\n  min-width: 13rem;\n  max-height: 70vh;\n  overflow: auto;\n  margin: 0;\n  padding: 6px;\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-box);\n  background: var(--tempra-color-bg);\n  box-shadow: var(--tempra-shadow);\n  list-style: none;\n  font-size: var(--tempra-text-ui);\n}\n\n.menu-list.start {\n  left: 0;\n}\n\n.menu-list.end {\n  right: 0;\n}\n\n/* A menu at the foot of the sidebar opens upwards. */\n.menu-list.up {\n  top: auto;\n  bottom: calc(100% + 6px);\n}\n\n.menu-list a,\n.menu-list button {\n  display: block;\n  width: 100%;\n  padding: 6px 10px;\n  border: 0;\n  border-radius: var(--tempra-radius-row);\n  background: none;\n  color: var(--tempra-color-text);\n  font-size: var(--tempra-text-ui);\n  text-align: left;\n  text-decoration: none;\n}\n\n.menu-list a:hover,\n.menu-list button:hover:not(:disabled),\n.menu-list a[aria-current=\"page\"] {\n  background: var(--tempra-color-hover);\n}\n\n.menu-list .menu-note {\n  padding: 6px 10px 2px;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-label);\n  letter-spacing: 0.04em;\n  text-transform: uppercase;\n}\n\n.menu-list hr {\n  width: 100%;\n  margin: 4px 0;\n}\n\n.avatar {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  width: 26px;\n  height: 26px;\n  padding: 0;\n  border: 0;\n  border-radius: 50%;\n  background: var(--tempra-color-selected);\n  color: var(--tempra-color-text);\n  font-size: var(--tempra-text-initial);\n  font-weight: var(--tempra-weight-strong);\n}\n\n/* A round button holding one 16px glyph. */\n.icon-button {\n  position: relative;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  width: 30px;\n  height: 30px;\n  padding: 0;\n  border: 0;\n  background: transparent;\n  color: var(--tempra-color-muted);\n}\n\n.icon-button[aria-pressed=\"true\"],\n.icon-button[aria-pressed=\"true\"]:hover:not(:disabled) {\n  background: var(--tempra-color-text);\n  color: var(--tempra-color-bg);\n}\n\n.icon-button svg {\n  display: block;\n}\n\n.icon-button:hover:not(:disabled) {\n  color: var(--tempra-color-text);\n}\n\n/* A button with a glyph and a short word or count beside it (the comments toggle). */\n.icon-button.with-count {\n  gap: 6px;\n  width: auto;\n  padding: 0 10px;\n  border-radius: var(--tempra-radius-row);\n  font-size: var(--tempra-text-meta);\n  font-variant-numeric: tabular-nums;\n}\n\n.icon-button.with-count[aria-pressed=\"true\"],\n.icon-button.with-count[aria-pressed=\"true\"]:hover:not(:disabled) {\n  background: var(--tempra-color-selected);\n  color: var(--tempra-color-text);\n}\n\n/* The change dot (the one colour): solid for changed since the person looked, pulsing (.live)\n   for an agent writing now. */\n.change-dot {\n  display: inline-block;\n  width: var(--tempra-dot);\n  height: var(--tempra-dot);\n  border-radius: 50%;\n  background: var(--tempra-color-agent);\n  vertical-align: middle;\n}\n\n/* Someone's initials in a small round mark: a person on a light fill, an agent on ink. */\n.avatar-mark {\n  display: inline-grid;\n  flex: none;\n  place-items: center;\n  width: var(--tempra-avatar);\n  height: var(--tempra-avatar);\n  border-radius: 50%;\n  background: var(--tempra-color-selected);\n  color: var(--tempra-color-text);\n  font-size: var(--tempra-text-initial);\n  font-weight: var(--tempra-weight-strong);\n  line-height: 1;\n}\n\n.avatar-mark.agent {\n  background: var(--tempra-color-text);\n  color: var(--tempra-color-bg);\n}\n\n/* A dialog (a concept's properties, its agent notes, all its versions): a card in the top layer. */\n.dialog {\n  width: min(32rem, calc(100vw - 32px));\n  max-height: min(80dvh, 44rem);\n  padding: 0;\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-card);\n  background: var(--tempra-color-bg);\n  box-shadow: var(--tempra-shadow);\n  color: var(--tempra-color-text);\n}\n\n.dialog.wide {\n  width: min(40rem, calc(100vw - 32px));\n}\n\n.dialog::backdrop {\n  background: var(--tempra-color-scrim);\n}\n\n.dialog-head {\n  position: sticky;\n  top: 0;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 8px;\n  padding: 10px 10px 6px 18px;\n  background: var(--tempra-color-bg);\n}\n\n.dialog-head h2 {\n  margin: 0;\n  font-size: var(--tempra-text-name);\n  font-weight: var(--tempra-weight-strong);\n}\n\n.dialog-body {\n  padding: 4px 18px 18px;\n  font-size: var(--tempra-text-ui);\n}\n\n/* A confirmation: what happens, then the action and Cancel. */\n.confirm-body p {\n  margin: 0 0 var(--tempra-space-2);\n}\n\n/* ---------- A page's column: the account's pages, settings, the library's tools ---------- */\n\n/* One centred column; the frame's top bar and sidebar are around it. */\n.page-column,\n.page {\n  width: 100%;\n  max-width: var(--tempra-page-width);\n  margin: 0 auto;\n  padding: 72px var(--tempra-page-pad) 96px;\n}\n\n.page-column.wide {\n  max-width: 960px;\n}\n\n/* The New pill: an outlined pill with a plus. */\n.pill-button,\na.button.pill-button {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  padding: 6px 12px 6px 8px;\n}\n\n/* The library list (take 4, board 01): cards under Yours and Shared with you. Each card has a\n   quiet cover (the library's tile; an agent's latest change at the right), then its name, what\n   is for the person there, its description and one line of facts. */\n.lib-cards {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));\n  gap: 16px;\n  margin: 0 0 var(--tempra-space-4);\n  padding: 0;\n  list-style: none;\n}\n\n.lib-card {\n  display: flex;\n  flex-direction: column;\n  min-width: 0;\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-box);\n  color: var(--tempra-color-text);\n  text-decoration: none;\n  overflow: hidden;\n}\n\n.lib-card:visited {\n  color: var(--tempra-color-text);\n}\n\n.lib-card:hover {\n  border-color: var(--tempra-color-border-strong);\n}\n\n.lib-card-cover {\n  display: flex;\n  align-items: flex-start;\n  justify-content: space-between;\n  gap: 8px;\n  min-height: 112px;\n  padding: 16px;\n  background: var(--tempra-color-ground);\n}\n\n.lib-card-cover .lib-tile {\n  width: 28px;\n  height: 28px;\n}\n\n.lib-card-live {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-meta);\n}\n\n.lib-card-body {\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n  padding: 14px 16px 16px;\n}\n\n.lib-card-name {\n  display: flex;\n  align-items: baseline;\n  justify-content: space-between;\n  gap: 8px;\n  font-size: var(--tempra-text-name);\n  font-weight: var(--tempra-weight-medium);\n}\n\n.lib-card-for {\n  flex: none;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-meta);\n  font-weight: var(--tempra-weight-regular);\n}\n\n.lib-card-desc {\n  margin: 0;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-ui);\n}\n\n.lib-card-meta {\n  margin: 4px 0 0;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-meta);\n}\n\n/* A section of the list (Yours, Shared with you). */\n.lib-section-title {\n  margin: 0 0 12px;\n  font-size: var(--tempra-text-reader);\n  font-weight: var(--tempra-weight-strong);\n}\n\n/* ---------- The workspace: the top bar, the sidebar, the page ---------- */\n\n.workspace {\n  display: grid;\n  grid-template-columns: var(--tempra-sidebar) minmax(0, 1fr);\n  grid-template-rows: var(--tempra-topbar) minmax(0, 1fr);\n  grid-template-areas:\n    \"topbar topbar\"\n    \"sidebar main\";\n  height: 100dvh;\n}\n\n.workspace.sidebar-hidden {\n  grid-template-columns: minmax(0, 1fr);\n  grid-template-areas:\n    \"topbar\"\n    \"main\";\n}\n\n/* The top bar: across the whole window, a hairline under it, split at the sidebar's edge. */\n.ws-topbar {\n  grid-area: topbar;\n  display: grid;\n  grid-template-columns: var(--tempra-sidebar) minmax(0, 1fr);\n  min-width: 0;\n  border-bottom: 1px solid var(--tempra-color-border);\n  background: var(--tempra-color-bg);\n}\n\n.sidebar-hidden .ws-topbar {\n  grid-template-columns: auto minmax(0, 1fr);\n}\n\n/* Over the sidebar: the mark, the library switcher (or the frame's name), search. */\n.topbar-brand {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  min-width: 0;\n  padding: 0 12px 0 16px;\n  border-right: 1px solid var(--tempra-color-border);\n}\n\n.topbar-brand .lib-tile {\n  width: 28px;\n  height: 28px;\n}\n\n/* A hairline between the mark and the name. */\n.topbar-brand .brand-sep {\n  width: 1px;\n  height: 20px;\n  margin: 0 2px;\n  background: var(--tempra-color-border);\n}\n\n/* The frame's name where there is no library to switch: Tempra, Settings, Library settings. */\n.topbar-name {\n  flex: 1;\n  min-width: 0;\n  overflow: hidden;\n  color: var(--tempra-color-text);\n  font-size: var(--tempra-text-name);\n  font-weight: var(--tempra-weight-strong);\n  text-decoration: none;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.topbar-name:visited {\n  color: var(--tempra-color-text);\n}\n\n/* The library switcher: the library's name and a chevron, in a quiet pill. */\n.lib-switch {\n  display: flex;\n  flex: 1;\n  align-items: center;\n  gap: 6px;\n  min-width: 0;\n  padding: 6px 8px;\n  border: 0;\n  border-radius: var(--tempra-radius-row);\n  background: transparent;\n  color: var(--tempra-color-text);\n  font-size: var(--tempra-text-name);\n  font-weight: var(--tempra-weight-strong);\n  text-align: left;\n}\n\n.lib-switch:hover:not(:disabled),\n.lib-switch[aria-expanded=\"true\"] {\n  background: var(--tempra-color-hover);\n}\n\n.lib-switch .lib-name {\n  flex: 1;\n  min-width: 0;\n}\n\n.lib-switch svg {\n  flex: none;\n  color: var(--tempra-color-faint);\n}\n\n/* The round search button, at the brand's right. */\n.search-button {\n  flex: none;\n  width: 36px;\n  height: 36px;\n  border: 1px solid var(--tempra-color-border);\n  border-radius: 50%;\n  background: var(--tempra-color-bg);\n}\n\n/* Over the page: the way back to the sidebar when it is hidden, the crumbs, then the page's\n   tools, the bell and the avatar. */\n.topbar-page {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  min-width: 0;\n  padding: 0 16px 0 20px;\n}\n\n.topbar-crumbs {\n  display: flex;\n  flex: 1;\n  align-items: center;\n  gap: 8px;\n  min-width: 0;\n}\n\n/* The page's tools (a concept's Comments, Copy page and ⋯), from the page itself. */\n.topbar-tools {\n  display: flex;\n  flex: none;\n  align-items: center;\n  gap: 6px;\n}\n\n.topbar-tools:empty {\n  display: none;\n}\n\n.topbar-end {\n  display: flex;\n  flex: none;\n  align-items: center;\n  gap: 6px;\n}\n\n/* The crumbs in the top bar: the folders, then the page, in the app's text size. */\n.crumbs {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n  min-width: 0;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-font-size);\n}\n\n.crumbs a {\n  color: inherit;\n  text-decoration: none;\n}\n\n.crumbs a:hover {\n  color: var(--tempra-color-text);\n}\n\n.crumbs .here {\n  color: var(--tempra-color-text);\n  font-weight: var(--tempra-weight-medium);\n}\n\n/* A control in the top bar that reads as a pill: Comments n, Copy page. */\n.topbar-tools .icon-button.with-count,\n.tool-pill {\n  height: 36px;\n  padding: 0 14px;\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-pill);\n  background: var(--tempra-color-bg);\n  color: var(--tempra-color-text);\n  font-size: var(--tempra-text-ui);\n}\n\n.tool-pill {\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n}\n\n.topbar-tools .icon-button:not(.with-count),\n.topbar-end .icon-button {\n  width: 36px;\n  height: 36px;\n  border: 1px solid var(--tempra-color-border);\n  border-radius: 50%;\n  color: var(--tempra-color-text);\n}\n\n.topbar-tools .icon-button.with-count[aria-pressed=\"true\"],\n.topbar-tools .icon-button.with-count[aria-pressed=\"true\"]:hover:not(:disabled) {\n  background: var(--tempra-color-selected);\n  color: var(--tempra-color-text);\n}\n\n/* The bell: the Inbox and its unread count as a small badge on the button's corner. */\n.bell .badge {\n  position: absolute;\n  top: -4px;\n  right: -4px;\n  display: grid;\n  place-items: center;\n  min-width: 16px;\n  height: 16px;\n  padding: 0 4px;\n  border-radius: var(--tempra-radius-pill);\n  background: var(--tempra-color-text);\n  color: var(--tempra-color-bg);\n  font-size: var(--tempra-text-initial);\n  font-weight: var(--tempra-weight-strong);\n  line-height: 1;\n}\n\n/* The bell's popover: the latest few items, Mark all read above, Open inbox below. */\n.bell-pop {\n  width: min(360px, calc(100vw - 32px));\n  padding: 0;\n}\n\n.bell-pop-head {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 8px;\n  padding: 12px 16px 10px;\n  border-bottom: 1px solid var(--tempra-color-border);\n  font-size: var(--tempra-text-name);\n  font-weight: var(--tempra-weight-strong);\n}\n\n.bell-pop-head button {\n  width: auto;\n  padding: 0;\n  border: 0;\n  background: none;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-ui);\n  font-weight: var(--tempra-weight-regular);\n}\n\n.bell-pop-head button:hover:not(:disabled) {\n  color: var(--tempra-color-text);\n}\n\n.menu-list .bell-item {\n  display: grid;\n  grid-template-columns: 20px minmax(0, 1fr) auto;\n  gap: 2px 10px;\n  padding: 10px 16px;\n  border-bottom: 1px solid var(--tempra-color-border);\n  border-radius: 0;\n}\n\n.bell-item .lib-tile {\n  grid-row: span 2;\n  width: 20px;\n  height: 20px;\n  font-size: var(--tempra-text-label);\n}\n\n.bell-item-what {\n  color: var(--tempra-color-text);\n  font-size: var(--tempra-text-ui);\n}\n\n.bell-item-what strong {\n  font-weight: var(--tempra-weight-medium);\n}\n\n/* The Inbox row's detail line, under the page's title (F-14). */\n.bell-item-detail {\n  display: block;\n  color: var(--tempra-color-muted);\n}\n\n.bell-item-where {\n  grid-column: 2;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-meta);\n}\n\n.bell-item .unread-dot {\n  grid-column: 3;\n  grid-row: span 2;\n  align-self: center;\n  width: var(--tempra-dot);\n  height: var(--tempra-dot);\n  border-radius: 50%;\n  background: var(--tempra-color-text);\n}\n\n.menu-list .bell-foot {\n  padding: 10px 16px;\n  border-radius: 0;\n  color: var(--tempra-color-muted);\n  text-align: center;\n}\n\n.menu-list .bell-empty {\n  padding: 24px 16px;\n  color: var(--tempra-color-muted);\n  text-align: center;\n}\n\n.menu-list .bell-empty button {\n  width: auto;\n  margin-left: var(--tempra-space-1);\n}\n\n/* Live updates stopped, quietly (F-19): a word before search and the bell; empty, nothing. */\n.feed-status {\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-meta);\n  white-space: nowrap;\n}\n\n.feed-status:empty {\n  display: none;\n}\n\n/* The avatar's menu: who, then the pages, the theme, sign out, each with its glyph. */\n.menu-list.account {\n  min-width: 15rem;\n}\n\n.menu-list .menu-person {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  padding: 8px 10px 10px;\n  color: var(--tempra-color-text);\n}\n\n.menu-person .avatar-mark {\n  width: 32px;\n  height: 32px;\n  font-size: var(--tempra-text-label);\n}\n\n.menu-person-names {\n  display: flex;\n  flex-direction: column;\n  min-width: 0;\n  line-height: var(--tempra-leading-tight);\n}\n\n.menu-person-names .email {\n  overflow-wrap: anywhere;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-meta);\n}\n\n.menu-list a.menu-item,\n.menu-list button.menu-item {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n}\n\n.menu-item svg {\n  flex: none;\n  color: var(--tempra-color-muted);\n}\n\n/* The theme row: its name, then System, Light, Dark as one small segmented control. */\n.menu-list .menu-theme {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  padding: 6px 10px;\n  font-size: var(--tempra-text-ui);\n}\n\n.menu-theme svg {\n  flex: none;\n  color: var(--tempra-color-muted);\n}\n\n.menu-theme .segmented {\n  margin-left: auto;\n}\n\n.menu-theme .segmented button {\n  padding: 2px 8px;\n  font-size: var(--tempra-text-meta);\n}\n\n/* The library switcher's menu: libraries as rows with their tile and, when shared, the role. */\n.menu-list.libraries {\n  min-width: 17rem;\n}\n\n.menu-list a.menu-lib {\n  display: grid;\n  grid-template-columns: 20px minmax(0, 1fr) auto;\n  gap: 0 10px;\n  align-items: center;\n  padding: 6px 10px;\n}\n\n.menu-lib .lib-tile {\n  grid-row: span 2;\n  width: 20px;\n  height: 20px;\n  font-size: var(--tempra-text-label);\n}\n\n.menu-lib .menu-lib-role {\n  grid-column: 2;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-meta);\n}\n\n.menu-lib .menu-lib-check {\n  grid-column: 3;\n  grid-row: span 2;\n  display: inline-flex;\n  color: var(--tempra-color-muted);\n}\n\n/* The sidebar: a hairline on its right; the views, a rule, the files (which scroll), and\n   Settings at its foot. A settings frame holds a way back and its tabs instead. */\n.ws-sidebar {\n  grid-area: sidebar;\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n  min-width: 0;\n  min-height: 0;\n  padding: 12px 10px;\n  border-right: 1px solid var(--tempra-color-border);\n  background: var(--tempra-color-bg);\n  font-size: var(--tempra-text-ui);\n}\n\n.ws-sidebar[hidden] {\n  display: none;\n}\n\n.sidebar-rule {\n  margin: 10px 8px;\n}\n\n.sidebar-label {\n  margin: 14px 10px 4px;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-meta);\n}\n\n.sidebar-scroll {\n  flex: 1;\n  min-height: 0;\n  overflow: auto;\n  padding-bottom: 16px;\n}\n\n.sidebar-foot {\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n  padding-top: 8px;\n}\n\n/* The way back at the top of a settings sidebar: \"‹ Back to tempra-dev\". */\n.nav-row.back {\n  margin-bottom: 14px;\n  color: var(--tempra-color-muted);\n}\n\n.nav-row.back:hover {\n  color: var(--tempra-color-text);\n}\n\n/* A library in the account's sidebar: its tile, its name, what is for the person there. */\n.nav-row .lib-tile {\n  width: 20px;\n  height: 20px;\n  font-size: var(--tempra-text-label);\n}\n\n.nav-row .lib-tile.shared {\n  border-radius: 50%;\n  background: var(--tempra-color-muted);\n}\n\n/* The page: the frame's scroller. Its width, not the window's, decides a concept's columns\n   (container queries on `page`, in concept.css), so hiding the\n   sidebar widens the reading layout. */\n.ws-main {\n  grid-area: main;\n  min-width: 0;\n  min-height: 0;\n  overflow: hidden auto;\n  background: var(--tempra-color-bg);\n  container: page / inline-size;\n}\n\n/* Showing the hidden sidebar: a quiet glyph at the left of the crumbs. */\n.show-sidebar {\n  flex: none;\n  color: var(--tempra-color-muted);\n}\n\n/* The change dot's second state (take 4): pulsing while an agent writes. */\n.change-dot.live {\n  background: var(--tempra-color-agent);\n  animation: tempra-pulse var(--tempra-pulse) ease-in-out infinite;\n}\n\n@keyframes tempra-pulse {\n  0%,\n  100% {\n    opacity: 1;\n    transform: scale(1);\n  }\n\n  50% {\n    opacity: 0.45;\n    transform: scale(0.7);\n  }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .change-dot.live {\n    animation: none;\n  }\n}\n\n.lib-tile,\n.wordmark-tile {\n  display: grid;\n  flex: none;\n  place-items: center;\n  width: 24px;\n  height: 24px;\n  border-radius: var(--tempra-radius-tile);\n  background: var(--tempra-color-text);\n  color: var(--tempra-color-bg);\n  font-size: var(--tempra-text-name);\n  font-weight: var(--tempra-weight-strong);\n}\n\n.lib-name {\n  overflow: hidden;\n  font-weight: var(--tempra-weight-strong);\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.nav {\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n}\n\n/* A row in the sidebar: a glyph, a name, a count or mark at the end. */\n.nav-row {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  width: 100%;\n  min-height: var(--tempra-row);\n  padding: 4px 10px;\n  border: 0;\n  border-radius: var(--tempra-radius-row);\n  background: transparent;\n  color: var(--tempra-color-text);\n  font-size: var(--tempra-text-ui);\n  text-align: left;\n  text-decoration: none;\n}\n\n.nav-row:visited {\n  color: var(--tempra-color-text);\n}\n\n.nav-row:hover,\n.nav-row:hover:not(:disabled) {\n  background: var(--tempra-color-hover);\n  color: var(--tempra-color-text);\n}\n\n.nav-row[aria-current=\"page\"],\n.nav-row[aria-current=\"location\"] {\n  background: var(--tempra-color-selected);\n  font-weight: var(--tempra-weight-medium);\n}\n\n.nav-row svg {\n  flex: none;\n}\n\n.nav-label {\n  flex: 1;\n  min-width: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.nav-count {\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-meta);\n  font-variant-numeric: tabular-nums;\n}\n\n.nav-row.person {\n  padding-left: 8px;\n}\n\n.nav-row.person .avatar-mark {\n  margin-right: 0;\n}\n\n/* The tree: nested lists, one row per folder or file, indented a step a level. A folder's row is\n   its chevron (a button that opens and closes it, turning), its name (a link to its folder view)\n   and its count of concepts; a page's or a file's row is a link, a file's with a small icon. */\n.tree,\n.tree ul {\n  margin: 0;\n  padding: 0;\n  list-style: none;\n}\n\n.tree ul {\n  padding-left: 12px;\n}\n\n.tree li {\n  margin: 0;\n}\n\n.tree-row {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  min-height: var(--tempra-row);\n  margin-bottom: 1px;\n  padding: 0 10px 0 4px;\n  border-radius: var(--tempra-radius-row);\n  font-size: var(--tempra-text-ui);\n  white-space: nowrap;\n}\n\n.tree-row:hover {\n  background: var(--tempra-color-hover);\n}\n\n/* The whole row takes a click or a tap (P-2, TEMPRA-133): its link reaches over the row, and a\n   folder's chevron sits above that. */\n.tree-row {\n  position: relative;\n}\n\n.tree-row > a::after {\n  content: \"\";\n  position: absolute;\n  inset: 0;\n  border-radius: inherit;\n}\n\n.tree-row > .tree-chevron {\n  position: relative;\n  z-index: 1;\n}\n\n.tree-chevron {\n  flex: none;\n  display: flex;\n  align-self: stretch;\n  align-items: center;\n  justify-content: center;\n  width: 16px;\n  padding: 0;\n  border: 0;\n  border-radius: var(--tempra-radius-row);\n  background: none;\n  color: var(--tempra-color-faint);\n  cursor: pointer;\n}\n\n.tree-chevron:hover {\n  color: var(--tempra-color-text);\n}\n\n.tree-chevron svg {\n  width: 12px;\n  height: 12px;\n  transition: transform 0.15s ease;\n}\n\n.tree-chevron[aria-expanded=\"true\"] svg {\n  transform: rotate(90deg);\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .tree-chevron svg {\n    transition: none;\n  }\n}\n\n.tree-name {\n  flex: 1;\n  min-width: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.tree-count {\n  flex: none;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-label);\n  font-variant-numeric: tabular-nums;\n}\n\n.tree-row > a {\n  flex: 1;\n  min-width: 0;\n  overflow: hidden;\n  color: var(--tempra-color-muted);\n  text-decoration: none;\n  text-overflow: ellipsis;\n}\n\n.tree-row:has(> [aria-current=\"page\"]) {\n  background: var(--tempra-color-selected);\n}\n\n.tree-row.dir > a {\n  color: var(--tempra-color-text);\n}\n\n.tree-row > a[aria-current=\"page\"] {\n  color: var(--tempra-color-text);\n  font-weight: var(--tempra-weight-medium);\n}\n\n.tree-leaf {\n  flex: none;\n  display: flex;\n  justify-content: center;\n  width: 16px;\n  color: var(--tempra-color-faint);\n}\n\n/* Marks: an agent's change (a dot), open comments (a count), a clock (stale) or an hourglass\n   (stale soon). */\n.tree-mark {\n  display: inline-flex;\n  flex: none;\n  align-items: center;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-label);\n  font-variant-numeric: tabular-nums;\n}\n\n.tree-note {\n  padding: 4px 10px;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-meta);\n}\n\n/* ---------- The quick switcher ---------- */\n\n.switcher {\n  width: min(36rem, 90vw);\n  padding: 12px;\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-card);\n  background: var(--tempra-color-bg);\n  box-shadow: var(--tempra-shadow);\n  color: var(--tempra-color-text);\n}\n\n.switcher::backdrop {\n  background: var(--tempra-color-scrim);\n}\n\n.switcher-head input {\n  width: 100%;\n  border-radius: var(--tempra-radius-pill);\n}\n\n.switcher [role=\"listbox\"] {\n  margin-top: var(--tempra-space-2);\n}\n\n.switcher [role=\"option\"] {\n  padding: 6px 10px;\n  border-radius: var(--tempra-radius-row);\n  cursor: pointer;\n}\n\n.switcher [role=\"option\"][aria-selected=\"true\"] {\n  background: var(--tempra-color-selected);\n}\n\n/* Searching…, No results, or that search did not answer (F-12); empty, it takes no room. */\n.switcher-status {\n  margin: var(--tempra-space-2) 10px 0;\n}\n\n.switcher-status:empty {\n  display: none;\n}\n\n/* ---------- A phone: a top bar, the sidebar as a drawer (take 4, boards 33 to 36) ---------- */\n\n/* The phone's pieces of the top bar (the menu button, where the person is, search), of the\n   drawer (its head, its search field, the Inbox row at its foot) and the dimmed page behind it\n   show only here. */\n.ws-menu,\n.ws-topbar-place,\n.phone-search,\n.drawer-head,\n.drawer-search,\n.ws-scrim,\n.phone-only {\n  display: none;\n}\n\n@media (max-width: 900px) {\n  .workspace,\n  .workspace.sidebar-hidden {\n    grid-template-columns: minmax(0, 1fr);\n    grid-template-rows: var(--tempra-bar) minmax(0, 1fr);\n    grid-template-areas:\n      \"topbar\"\n      \"main\";\n  }\n\n  /* The bar: the menu button, where the person is, then on a concept Comments n and ⋯, on\n     other pages search and the bell; the avatar last. */\n  .ws-topbar,\n  .sidebar-hidden .ws-topbar {\n    display: flex;\n    align-items: center;\n    padding: 0 12px 0 6px;\n  }\n\n  .topbar-brand,\n  .topbar-crumbs,\n  .show-sidebar,\n  .has-tools .topbar-end .bell,\n  .has-tools .phone-search {\n    display: none;\n  }\n\n  .topbar-page {\n    flex: 1;\n    gap: 8px;\n    padding: 0;\n  }\n\n  /* The way to everything else, in ink so it reads as the bar's first control. */\n  .ws-menu {\n    display: inline-flex;\n    flex: none;\n    color: var(--tempra-color-text);\n  }\n\n  .phone-search {\n    display: inline-flex;\n  }\n\n  .nav-row.phone-only {\n    display: flex;\n  }\n\n  /* Where the person is: the library on its home, a page by its name, a concept by its title. */\n  .ws-topbar-place {\n    display: block;\n    flex: 1;\n    min-width: 0;\n    padding: 0 4px;\n    overflow: hidden;\n    color: var(--tempra-color-text);\n    font-size: var(--tempra-text-name);\n    font-weight: var(--tempra-weight-medium);\n    text-overflow: ellipsis;\n    white-space: nowrap;\n  }\n\n  /* The bar's controls keep their desktop shape; each answers a 44px touch around it. */\n  .topbar-page .icon-button::after,\n  .topbar-page .avatar::after {\n    content: \"\";\n    position: absolute;\n    inset: min(0px, calc((100% - var(--tempra-touch)) / 2));\n  }\n\n  .topbar-page .avatar {\n    position: relative;\n    width: 36px;\n    height: 36px;\n  }\n\n  /* The drawer (board 34): about four fifths of the screen, over the top bar, the page dimmed\n     behind it. At its head the mark, the switcher and ×; then search, Home, Activity, a rule,\n     the tree; Settings and the Inbox at its foot. */\n  .ws-scrim {\n    position: fixed;\n    inset: 0;\n    z-index: 7;\n    display: block;\n    background: var(--tempra-color-scrim);\n  }\n\n  .ws-sidebar {\n    position: fixed;\n    top: 0;\n    bottom: 0;\n    left: 0;\n    z-index: 8;\n    display: none;\n    width: var(--tempra-drawer);\n    padding: 0 12px 8px;\n    border-right: 1px solid var(--tempra-color-border);\n    background: var(--tempra-color-bg);\n    box-shadow: var(--tempra-shadow);\n  }\n\n  .ws-sidebar.open {\n    display: flex;\n  }\n\n  .ws-sidebar:focus {\n    outline: none;\n  }\n\n  .drawer-head {\n    display: flex;\n    flex: none;\n    align-items: center;\n    gap: 8px;\n    min-height: var(--tempra-topbar);\n    margin: 0 -12px 12px;\n    padding: 0 8px 0 16px;\n    border-bottom: 1px solid var(--tempra-color-border);\n  }\n\n  .drawer-head .brand-sep {\n    width: 1px;\n    height: 20px;\n    margin: 0 2px;\n    background: var(--tempra-color-border);\n  }\n\n  /* Search is the field below; the head ends with ×. */\n  .drawer-head .search-button {\n    display: none;\n  }\n\n  .drawer-close {\n    flex: none;\n    color: var(--tempra-color-text);\n  }\n\n  /* Search, as a field at the drawer's top: it opens the quick switcher. */\n  .drawer-search {\n    display: flex;\n    flex: none;\n    align-items: center;\n    gap: 10px;\n    min-height: var(--tempra-touch);\n    margin-bottom: 12px;\n    padding: 0 16px;\n    border: 1px solid var(--tempra-color-border);\n    border-radius: var(--tempra-radius-pill);\n    background: var(--tempra-color-bg);\n    color: var(--tempra-color-muted);\n    font-size: var(--tempra-text-name);\n    text-align: left;\n  }\n\n  .drawer-search span {\n    overflow: hidden;\n    text-overflow: ellipsis;\n    white-space: nowrap;\n  }\n\n  .ws-sidebar .nav-row,\n  .ws-sidebar .tree-row {\n    font-size: var(--tempra-text-name);\n  }\n\n  .ws-sidebar .sidebar-foot {\n    margin: 0 -12px;\n    padding: 8px 12px 0;\n    border-top: 1px solid var(--tempra-color-border);\n  }\n\n  /* Touch targets: every row and control at least 44px tall. */\n  .nav-row,\n  .tree-row,\n  .lib-switch {\n    min-height: var(--tempra-touch);\n  }\n\n  .icon-button.touch {\n    width: var(--tempra-touch);\n    height: var(--tempra-touch);\n  }\n\n  .page-column,\n  .page {\n    padding: 32px 16px 72px;\n  }\n}\n\n/* ---------- Page pieces: lists, tables, forms ---------- */\n\n.new-library {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 8px;\n  margin: -12px 0 24px;\n  padding: 12px 18px;\n  border-radius: var(--tempra-radius-box);\n  background: var(--tempra-color-bg);\n  box-shadow: var(--tempra-shadow);\n  font-size: var(--tempra-text-ui);\n}\n\n.new-library .notice {\n  flex-basis: 100%;\n  margin: 0;\n}\n\n/* A command or URL to copy (the connect pages): an inset that wraps rather than widening the page. */\n.page pre,\n.page-column pre {\n  margin: 0 0 var(--tempra-space-3);\n  padding: 10px 14px;\n  border-radius: var(--tempra-radius-row);\n  background: var(--tempra-color-ground);\n  font-size: var(--tempra-text-ui);\n  line-height: var(--tempra-line-height);\n  white-space: pre-wrap;\n  overflow-wrap: anywhere;\n}\n\n.page-column pre,\n.page-column pre.src {\n  background: var(--tempra-color-ground);\n}\n\n/* Dates and short facts in a table keep to one line. */\ntable.list td.when,\ntable.list .nowrap {\n  white-space: nowrap;\n}\n\n.table-wrap {\n  overflow-x: auto;\n  margin: 0 0 var(--tempra-space-3);\n}\n\ntable.list {\n  width: 100%;\n  font-size: var(--tempra-text-ui);\n}\n\ntable.list th {\n  padding: 6px 10px;\n  border-bottom: 1px solid var(--tempra-color-border);\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-label);\n  font-weight: var(--tempra-weight-regular);\n  letter-spacing: 0.04em;\n  text-transform: uppercase;\n}\n\ntable.list td {\n  padding: 10px;\n  border-bottom: 1px solid var(--tempra-color-border);\n}\n\ntable.list td.name a {\n  font-weight: var(--tempra-weight-medium);\n}\n\n/* A setting on one line: its name, then its control (the Account page's theme). */\n.field-row {\n  display: flex;\n  align-items: center;\n  gap: 16px;\n}\n\n/* A group of related controls on a page (a form, a list with its actions). */\n.panel-box {\n  margin: 0 0 var(--tempra-space-4);\n  padding: 16px 18px;\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-box);\n  background: var(--tempra-color-bg);\n}\n\n.panel-box > h2:first-child {\n  margin-top: 0;\n}\n\nform.inline,\nform.filters,\nform.token {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 8px;\n}\n\n/* The ledger's filters: small labels, inset fields, no box. */\nform.filters {\n  margin: 0 0 var(--tempra-space-3);\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-meta);\n}\n\nform.filters label {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n}\n\nform.filters input {\n  padding: 4px 10px;\n  border: 0;\n  border-radius: var(--tempra-radius-pill);\n  background: var(--tempra-color-ground);\n  color: var(--tempra-color-text);\n}\n\nform.filters input[type=\"text\"] {\n  width: 9rem;\n}\n\nform.filters button {\n  padding: 4px 12px;\n  font-size: var(--tempra-text-meta);\n}\n\nform.token {\n  align-items: flex-start;\n  flex-direction: column;\n}\n\npre.src {\n  overflow-x: auto;\n  padding: 12px 14px;\n  border-radius: var(--tempra-radius-box);\n  background: var(--tempra-color-ground);\n  font-size: var(--tempra-text-meta);\n  line-height: var(--tempra-line-height);\n}\n\nul.events {\n  margin: 4px 0 0;\n  padding: 0;\n  list-style: none;\n  font-size: var(--tempra-text-ui);\n  line-height: var(--tempra-line-height);\n}\n\n/* ---------- Notifications (TEMPRA-72, TEMPRA-73): mentions (the Inbox is inbox.css) ---------- */\n\n/* The comment box with its @ suggestions under it. */\n.mention-box {\n  position: relative;\n}\n\n.mention-list [aria-selected=\"true\"] {\n  background: var(--tempra-color-hover);\n}\n\n/*\n * A concept's page (take 4, TEMPRA-114; tempra-dev: app/reader, decisions/one-panel-from-the-top-\n * bar): the text (title, description, byline, body, sources) centred in its column, and on the\n * right its contents, or one panel in their place (Comments, History, Properties). The page's\n * width decides what fits (container queries on `page`, the page's scroller): under 1100px the\n * contents hide (On this page under the byline), and a panel takes their column down to 960px\n * and overlays the page below that; on a phone (900px and under, the window's call) a panel is\n * a sheet from the bottom.\n */\n\n/* The right column is the panel's width whether it holds the contents or a panel, so opening a\n   panel takes the contents' space and never moves the text (C-17). */\n.concept-grid {\n  display: grid;\n  grid-template-columns: [text] minmax(0, 1fr) [side] var(--tempra-panel);\n  min-height: 100%;\n}\n\n/* The Markdown view has no contents (its headings lead nowhere there): the file takes the room. */\n.concept.markdown-on:not(.panel-open) .concept-grid {\n  grid-template-columns: [text] minmax(0, 1fr);\n}\n\n.concept .doc {\n  grid-row: 1;\n  grid-column: text;\n  justify-self: center;\n  width: 100%;\n  max-width: calc(var(--tempra-column-text) + 2 * var(--tempra-page-pad));\n  min-width: 0;\n  padding: 40px var(--tempra-page-pad) 140px;\n}\n\n/* The Markdown view is wider than the text: the file's lines are long. */\n.concept.markdown-on .doc {\n  max-width: calc(var(--tempra-measure) + 2 * var(--tempra-page-pad) + 200px);\n}\n\n.concept-side {\n  grid-row: 1;\n  grid-column: side;\n  min-width: 0;\n}\n\n/* The contents: the page's headings in small grey type, nested, kept in view; the section in\n   view marked with a rule. No heading over them. */\n.concept-contents {\n  position: sticky;\n  top: 0;\n  max-width: calc(var(--tempra-contents) + 2 * var(--tempra-page-pad));\n  max-height: calc(100dvh - var(--tempra-topbar));\n  overflow: auto;\n  padding: 48px var(--tempra-page-pad) 24px 0;\n}\n\n.toc {\n  margin: 0;\n  padding: 0;\n  border-left: 1px solid var(--tempra-color-border);\n  list-style: none;\n  font-size: var(--tempra-text-meta);\n  line-height: var(--tempra-line-height);\n}\n\n.toc a {\n  display: block;\n  margin-left: -1px;\n  padding: 4px 0 4px 14px;\n  border-left: 1px solid transparent;\n  color: var(--tempra-color-muted);\n  text-decoration: none;\n}\n\n.toc .sub a {\n  padding-left: 26px;\n}\n\n.toc a:hover {\n  color: var(--tempra-color-text);\n}\n\n.toc a[aria-current=\"location\"] {\n  border-left-color: var(--tempra-color-text);\n  color: var(--tempra-color-text);\n}\n\n/* \"On this page\" under the byline, for when the contents have no column. */\n.toc-inline {\n  display: none;\n  margin-top: 20px;\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-box);\n  font-size: var(--tempra-text-ui);\n}\n\n/* Closed by default: \"On this page\" and a chevron, turned while open (board 33). */\n.toc-inline summary {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  min-height: 40px;\n  padding: 0 16px;\n  color: var(--tempra-color-text);\n  list-style: none;\n  cursor: pointer;\n}\n\n.toc-inline summary::-webkit-details-marker {\n  display: none;\n}\n\n.toc-inline summary svg {\n  color: var(--tempra-color-faint);\n  transition: transform 0.15s ease;\n}\n\n.toc-inline[open] summary svg {\n  transform: rotate(180deg);\n}\n\n.toc-inline .toc {\n  margin: 0 16px 12px;\n}\n\n/* ---------- A panel: in the contents' column, its title, a count and × ---------- */\n\n.concept-panel {\n  position: sticky;\n  top: 0;\n  display: flex;\n  flex-direction: column;\n  height: calc(100dvh - var(--tempra-topbar));\n  border-left: 1px solid var(--tempra-color-border);\n  background: var(--tempra-color-bg);\n  font-size: var(--tempra-text-ui);\n}\n\n.panel-head {\n  display: flex;\n  flex: none;\n  align-items: center;\n  gap: 8px;\n  min-height: 56px;\n  padding: 0 12px 0 20px;\n  border-bottom: 1px solid var(--tempra-color-border);\n}\n\n.panel-head h2 {\n  margin: 0;\n  font-size: var(--tempra-text-ui);\n  font-weight: var(--tempra-weight-strong);\n}\n\n.panel-head .count {\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-meta);\n}\n\n.panel-head .icon-button {\n  margin-left: auto;\n}\n\n.panel-body {\n  flex: 1;\n  min-height: 0;\n  overflow: auto;\n  padding: 16px 20px 32px;\n}\n\n.panel-section {\n  margin-top: 24px;\n}\n\n.panel-section .label {\n  margin: 0 0 8px;\n}\n\n.panel-section .actions {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n  margin: 10px 0 0;\n}\n\n/* Check: Mark as checked, or how much changed since someone checked and Show changes. */\n.check {\n  padding: 12px 14px;\n  border-radius: var(--tempra-radius-box);\n  background: var(--tempra-color-ground);\n}\n\n.check-state {\n  margin: 0;\n}\n\n.check .actions:first-child {\n  margin-top: 0;\n}\n\n/* For agents (n): a closed disclosure at the foot of Properties. */\n.for-agents summary {\n  cursor: pointer;\n}\n\n.for-agents[open] summary {\n  margin-bottom: 8px;\n}\n\n.for-agents .facts {\n  margin-bottom: 12px;\n}\n\n/* Where a crumb notes what is exceptional (stale, a status that is not stable). */\n.crumb-flag {\n  color: var(--tempra-color-muted);\n}\n\n.crumb-flag::before {\n  content: \"·\";\n  margin-right: 6px;\n}\n\n.doc-head {\n  margin-bottom: 32px;\n}\n\n.doc-title {\n  margin: 0 0 12px;\n  font-family: var(--tempra-font-reader);\n  font-size: var(--tempra-text-title);\n  font-weight: var(--tempra-weight-medium);\n  line-height: var(--tempra-leading-tight);\n  letter-spacing: -0.01em;\n}\n\n.doc-tagline {\n  margin: 0;\n  color: var(--tempra-color-muted);\n  font-family: var(--tempra-font-reader);\n  font-size: var(--tempra-text-reader);\n  line-height: var(--tempra-line-height);\n}\n\n/* ---------- The byline: who wrote this version, for whom, when; or who is editing now ---------- */\n\n.byline {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 6px 8px;\n  margin-top: 20px;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-ui);\n}\n\n.byline-sep {\n  color: var(--tempra-color-faint);\n}\n\n/* Whether a person checked the page: one quiet line under the byline, only when someone has. */\n.doc-checked {\n  margin: 8px 0 0;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-ui);\n}\n\n.doc-checked a {\n  color: inherit;\n}\n\n.doc-checked a:hover {\n  color: var(--tempra-color-text);\n}\n\n.byline-live {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  color: var(--tempra-color-text);\n}\n\n/* ---------- History: the versions, newest first ---------- */\n\n.versions {\n  margin: 0;\n  padding: 0;\n  list-style: none;\n}\n\n.versions a.version {\n  display: grid;\n  grid-template-columns: 36px minmax(0, 1fr);\n  gap: 8px;\n  padding: 8px 10px;\n  border-radius: var(--tempra-radius-row);\n  color: var(--tempra-color-text);\n  text-decoration: none;\n}\n\n.versions a.version:hover {\n  background: var(--tempra-color-hover);\n}\n\n.versions a.version.chosen {\n  background: var(--tempra-color-selected);\n}\n\n.version-n {\n  color: var(--tempra-color-muted);\n  font-variant-numeric: tabular-nums;\n}\n\n.version-what {\n  display: flex;\n  flex-direction: column;\n  min-width: 0;\n}\n\n.version-note {\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.version-who {\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-meta);\n}\n\n.older-versions {\n  margin-top: 12px;\n  padding-left: 10px;\n  font-size: var(--tempra-text-meta);\n  text-decoration: underline;\n}\n\n/* ---------- Review mode, and the changes since a version chosen in History ---------- */\n\n.review-bar {\n  position: sticky;\n  top: 12px;\n  z-index: 2;\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 8px 16px;\n  margin: 0 0 32px;\n  padding: 8px 8px 8px 14px;\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-box);\n  background: var(--tempra-color-bg);\n  font-size: var(--tempra-text-ui);\n}\n\n.review-what {\n  flex: 1 1 16rem;\n  min-width: 0;\n}\n\n.review-lead {\n  font-weight: var(--tempra-weight-medium);\n}\n\n.review-actions {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 8px 12px;\n}\n\n.verify-form {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 6px;\n}\n\n.verify-form input {\n  flex: 1 1 10rem;\n  min-width: 0;\n}\n\n/* The changes in the text (take 4, board 22): a hairline warm rule left of each changed block,\n   insertions underlined on a grey ground, deletions struck through in grey (prose.css). */\n.concept\n  .prose\n  > :is(p, ul, ol, blockquote, pre, h2, h3, h4, h5, h6, .table):has(\n    ins.diff-added,\n    del.diff-removed\n  ) {\n  margin-left: -16px;\n  padding-left: 15px;\n  border-left: 1px solid var(--tempra-color-agent);\n}\n\n/* ---------- The end of the body: sources ---------- */\n\n.doc-sources {\n  max-width: var(--tempra-measure-reader);\n  margin-top: 56px;\n  padding-top: 20px;\n  border-top: 1px solid var(--tempra-color-border);\n}\n\n.doc-sources h2 {\n  margin: 0 0 12px;\n  font-size: var(--tempra-text-ui);\n  font-weight: var(--tempra-weight-strong);\n}\n\n.doc-sources h3 {\n  margin: 20px 0 8px;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-meta);\n  font-weight: var(--tempra-weight-medium);\n}\n\n.sources {\n  margin: 0;\n  padding: 0;\n  list-style: none;\n}\n\n.sources li {\n  display: grid;\n  grid-template-columns: 20px minmax(0, 1fr);\n  gap: 6px;\n  margin-bottom: 10px;\n  font-size: var(--tempra-text-ui);\n  line-height: var(--tempra-line-height);\n}\n\n.sources li:target {\n  background: var(--tempra-color-ground);\n}\n\n.sources .num {\n  color: var(--tempra-color-muted);\n  font-variant-numeric: tabular-nums;\n}\n\n.sources .meta {\n  display: block;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-meta);\n}\n\n.sources a {\n  color: var(--tempra-color-text);\n}\n\n/* ---------- The Markdown view: the stored file, with line numbers ---------- */\n\n.raw-head {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 8px 12px;\n  margin-bottom: 16px;\n}\n\n/* Wrap lines, pressed while long lines wrap. */\n.raw-head button[aria-pressed=\"true\"],\n.raw-head button[aria-pressed=\"true\"]:hover:not(:disabled) {\n  background: var(--tempra-color-selected);\n}\n\n.raw-path {\n  flex: 1;\n  min-width: 0;\n  color: var(--tempra-color-muted);\n  overflow-wrap: anywhere;\n}\n\n/* The file in a pre, a line per span; the numbers are CSS counters in the gutter, so they are\n   never selected or copied, and stay on their line when long lines wrap (Wrap lines). */\n.raw-file {\n  margin: 0;\n  padding: 16px 18px 16px calc(var(--raw-gutter) + 16px);\n  overflow-x: auto;\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-box);\n  background: var(--tempra-color-ground);\n  font-family: var(--tempra-font-mono);\n  font-size: var(--tempra-text-ui);\n  line-height: var(--tempra-line-height);\n  white-space: pre;\n  counter-reset: line;\n  --raw-gutter: 4ch;\n}\n\n.raw-file.wrap {\n  white-space: pre-wrap;\n  overflow-wrap: anywhere;\n}\n\n.raw-line {\n  position: relative;\n  counter-increment: line;\n}\n\n.raw-line::before {\n  content: counter(line);\n  position: absolute;\n  left: calc(-1 * var(--raw-gutter) - 12px);\n  width: var(--raw-gutter);\n  color: var(--tempra-color-muted);\n  font-variant-numeric: tabular-nums;\n  text-align: right;\n  user-select: none;\n}\n\n/* ---------- Properties: the facts, links, agent notes ---------- */\n\n.facts {\n  display: grid;\n  grid-template-columns: 6.5rem minmax(0, 1fr);\n  margin: 0;\n  font-size: var(--tempra-text-ui);\n}\n\n.facts > div {\n  display: contents;\n}\n\n.facts dt,\n.facts dd {\n  padding: 9px 0;\n  border-bottom: 1px solid var(--tempra-color-border);\n  line-height: var(--tempra-line-height);\n}\n\n.facts dt {\n  color: var(--tempra-color-muted);\n}\n\n.facts dd {\n  min-width: 0;\n  margin: 0;\n  overflow-wrap: anywhere;\n}\n\n.facts pre {\n  margin: 0;\n  white-space: pre-wrap;\n}\n\n.linked {\n  margin: 0;\n  padding-left: 18px;\n}\n\n.linked li,\n.notes-list li {\n  margin-bottom: 8px;\n  font-size: var(--tempra-text-meta);\n}\n\n.notes-list {\n  margin: 0;\n  padding: 0;\n  list-style: none;\n}\n\n/* ---------- What fits: the page's width decides ---------- */\n\n/* No room beside the text: the contents move under the byline, and a panel overlays the page. */\n@container page (width < 1100px) {\n  .concept-grid,\n  .concept.panel-open .concept-grid {\n    grid-template-columns: [text] minmax(0, 1fr);\n  }\n\n  /* Its column is gone: what it holds is hidden (the contents) or fixed (a panel). */\n  .concept-side {\n    display: contents;\n  }\n\n  .concept-contents {\n    display: none;\n  }\n\n  .toc-inline {\n    display: block;\n  }\n\n  .concept-panel {\n    position: fixed;\n    top: var(--tempra-topbar);\n    right: 0;\n    bottom: 0;\n    z-index: 5;\n    width: min(var(--tempra-panel), 100vw);\n    height: auto;\n    box-shadow: var(--tempra-shadow);\n  }\n}\n\n/* What an overlaid panel dims: the page, the top bar and the sidebar, which are inert while it\n   is open (TEMPRA-133). The app draws it only then; a tap on it closes the panel. */\n.panel-scrim {\n  position: fixed;\n  inset: 0;\n  z-index: 4;\n  background: var(--tempra-color-scrim);\n}\n\n/* Room for the text and a panel, not the contents as well (a laptop of about 1280px with the\n   sidebar shown): an open panel takes a column again and the text moves over for it, so nothing\n   (On this page included) runs under it. Narrower than this, it overlays. */\n@container page (960px <= width < 1100px) {\n  .concept.panel-open .concept-grid {\n    grid-template-columns: [text] minmax(0, 1fr) [side] var(--tempra-panel);\n  }\n\n  .concept.panel-open .concept-side {\n    display: block;\n  }\n\n  .concept.panel-open .concept-panel {\n    position: sticky;\n    top: 0;\n    right: auto;\n    bottom: auto;\n    z-index: auto;\n    width: auto;\n    height: calc(100dvh - var(--tempra-topbar));\n    box-shadow: none;\n  }\n}\n\n/* The crumbs under the phone's top bar (board 33): the concept's folders and what is exceptional,\n   over the title. Elsewhere the top bar holds them. */\n.doc-crumbs {\n  display: none;\n}\n\n/* A phone (take 4, boards 33 and 35): one column with a 16px gutter, \"On this page\" as a closed\n   disclosure under the byline, and a panel as a sheet from the bottom, the page dimmed behind. */\n@media (max-width: 900px) {\n  .concept .doc {\n    padding: 16px 16px 96px;\n  }\n\n  .doc-crumbs {\n    display: flex;\n    flex-wrap: wrap;\n    gap: 6px;\n    margin-bottom: 12px;\n    color: var(--tempra-color-muted);\n    font-size: var(--tempra-text-ui);\n  }\n\n  .doc-crumbs:empty {\n    display: none;\n  }\n\n  .doc-crumbs a {\n    color: inherit;\n    text-decoration: none;\n  }\n\n  .doc-title {\n    font-size: var(--tempra-text-page);\n  }\n\n  /* On a phone the top bar has Comments and ⋯; Copy page heads ⋯ (TEMPRA-118). Comments\n     reads as its word and count, without the glyph, to leave the page's name room. */\n  .topbar-tools .copy-page,\n  .comments-toggle svg {\n    display: none;\n  }\n\n  .toc-inline summary {\n    min-height: var(--tempra-touch);\n    font-size: var(--tempra-text-name);\n  }\n\n  .toc-inline .toc a {\n    padding-top: 8px;\n    padding-bottom: 8px;\n  }\n\n  .concept-panel {\n    top: auto;\n    right: 0;\n    bottom: 0;\n    left: 0;\n    z-index: 7;\n    width: auto;\n    height: var(--tempra-sheet);\n    border-top: 1px solid var(--tempra-color-border);\n    border-left: 0;\n    border-radius: var(--tempra-radius-card) var(--tempra-radius-card) 0 0;\n    box-shadow: none;\n  }\n\n  /* The page dimmed behind the sheet, the top bar too (.panel-scrim). */\n  .panel-scrim {\n    z-index: 6;\n  }\n\n  .panel-head {\n    position: relative;\n    min-height: 64px;\n    padding: 12px 8px 0 20px;\n    touch-action: none;\n  }\n\n  .panel-head h2 {\n    font-size: var(--tempra-text-name);\n  }\n\n  /* The drag handle, centred at the sheet's top edge. */\n  .panel-grip {\n    position: absolute;\n    top: 8px;\n    left: 50%;\n    width: 36px;\n    height: 4px;\n    border-radius: var(--tempra-radius-pill);\n    background: var(--tempra-color-border-strong);\n    transform: translateX(-50%);\n  }\n\n  .panel-body {\n    padding: 16px 16px 24px;\n    overscroll-behavior: contain;\n  }\n}\n\n/* The handle is the phone sheet's alone. */\n@media (min-width: 901px) {\n  .panel-grip {\n    display: none;\n  }\n}\n\n/*\n * Comments on a concept (take 4, TEMPRA-114; tempra-dev: app/comments): the threads in the\n * Comments panel (its frame is concept.css's), Open and Resolved n, a draft at the top while one\n * is written, the active thread as a card, the others compact (their quote, then who, the first\n * words, when). Lines and greys only: no colour.\n */\n\n.comments-list {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n\n.comments-list .segmented {\n  align-self: flex-start;\n  margin-bottom: 6px;\n}\n\n/* \"Comment on the page\": a quiet pill, outlined, at the top of the list. */\n.new-thread {\n  align-self: flex-start;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-meta);\n}\n\n.new-thread:hover:not(:disabled) {\n  color: var(--tempra-color-text);\n}\n\n/* A thread whose quote is gone from the body: said in words, as a small outlined label. */\n.thread-outdated {\n  align-self: flex-start;\n  padding: 0 8px;\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-pill);\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-meta);\n  font-style: normal;\n  line-height: var(--tempra-line-height);\n}\n\n/* A compact thread: its quote, then one line: who, the first words, when. */\n.thread.collapsed {\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n  width: 100%;\n  padding: 10px 12px;\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-box);\n  background: transparent;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-meta);\n  text-align: left;\n}\n\n.thread-meta {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  width: 100%;\n  min-width: 0;\n}\n\n.thread.collapsed .thread-quote {\n  display: -webkit-box;\n  overflow: hidden;\n  -webkit-box-orient: vertical;\n  -webkit-line-clamp: 2;\n}\n\n.thread.collapsed:hover:not(:disabled) {\n  background: var(--tempra-color-hover);\n}\n\n.thread.collapsed .avatar-mark {\n  width: var(--tempra-avatar-small);\n  height: var(--tempra-avatar-small);\n  font-size: var(--tempra-text-initial);\n}\n\n.thread.collapsed .agent-name {\n  flex: none;\n  max-width: 60%;\n  overflow: hidden;\n  color: var(--tempra-color-text);\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.thread.collapsed .agent-name b,\n.said-by .agent-name b {\n  font-weight: var(--tempra-weight-medium);\n}\n\n.thread.collapsed .agent-for,\n.said-by .agent-for {\n  color: var(--tempra-color-muted);\n}\n\n.thread-words {\n  flex: 1;\n  min-width: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.thread-replies {\n  flex: none;\n  color: var(--tempra-color-muted);\n  font-variant-numeric: tabular-nums;\n}\n\n.thread.collapsed time {\n  flex: none;\n  color: var(--tempra-color-muted);\n}\n\n/* A resolved thread reads quieter: muted text, never faded below AA (TEMPRA-132). */\n.thread.resolved,\n.thread.resolved .agent-name {\n  color: var(--tempra-color-muted);\n}\n\n/* The active thread (and a new comment): a card with the comments, a reply, Resolve. */\n.thread.open {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n  padding: 12px;\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-box);\n  background: var(--tempra-color-bg);\n}\n\n.said-by {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  font-size: var(--tempra-text-meta);\n}\n\n.said-by time,\n.said-change {\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-meta);\n}\n\n.said-change {\n  margin: 0;\n}\n\n.comment {\n  margin: 4px 0 0 calc(var(--tempra-avatar) + 8px);\n  font-size: var(--tempra-text-ui);\n  line-height: var(--tempra-line-height);\n  white-space: pre-wrap;\n  overflow-wrap: anywhere;\n}\n\n.quote {\n  margin: 0;\n  padding-left: 10px;\n  border-left: 2px solid var(--tempra-color-border-strong);\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-meta);\n  font-style: italic;\n  line-height: var(--tempra-line-height);\n  white-space: pre-wrap;\n  overflow-wrap: anywhere;\n}\n\n.quote a {\n  color: inherit;\n  text-decoration: none;\n}\n\n/* The reply field, a pill until it has words; the composer's field, a box. */\n.reply-form,\n.comment-form {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n\n.reply-form textarea,\n.comment-form textarea {\n  display: block;\n  width: 100%;\n  border: 0;\n  background: var(--tempra-color-ground);\n  font-size: var(--tempra-text-meta);\n}\n\n.reply-form textarea {\n  height: 2rem;\n  min-height: 0;\n  padding: 5px 12px;\n  border-radius: var(--tempra-radius-pill);\n  resize: none;\n}\n\n.reply-form textarea:focus,\n.reply-form textarea:not(:placeholder-shown) {\n  height: 4rem;\n  border-radius: var(--tempra-radius-box);\n}\n\n.comment-form textarea {\n  min-height: 4rem;\n  padding: 8px 10px;\n  border-radius: var(--tempra-radius-row);\n  resize: vertical;\n}\n\n.reply-form .actions,\n.comment-form .actions {\n  display: flex;\n  justify-content: flex-end;\n  gap: 6px;\n  margin: 0;\n}\n\n.reply-form button,\n.comment-form button {\n  padding: 4px 12px;\n  font-size: var(--tempra-text-meta);\n}\n\n/* The active thread's card is drawn in ink, as its quote's highlight is filled. */\nsection.thread.open {\n  border-color: var(--tempra-color-text);\n}\n\n/* On a phone, a compact thread is a touch target. */\n@media (max-width: 900px) {\n  .thread.collapsed {\n    min-height: var(--tempra-touch);\n  }\n}\n\n/*\n * The person's views of a library (take 3, TEMPRA-106; take 4, TEMPRA-115 and 117; tempra-dev:\n * app/home, app/activity, app/workspace): the library's home, Activity,\n * a folder, an attachment and Not found. Quiet pages in one column: a header, then sections of rows.\n */\n\n/* ---------- Shared: a page's header and its sections ---------- */\n\n/* The header: the title (a concept title's look) and a quiet line, a link at the right. */\n.view-head {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: flex-end;\n  gap: var(--tempra-space-2) var(--tempra-space-3);\n  margin-bottom: var(--tempra-space-4);\n}\n\n.view-head-main {\n  display: flex;\n  flex: 1;\n  flex-direction: column;\n  gap: var(--tempra-space-1);\n  min-width: 0;\n}\n\n/* A view is the app, not a document: its title is the app's sans, sized as an h1 (TEMPRA-108). */\n.view-title {\n  margin: 0;\n  font-size: var(--tempra-text-page);\n  font-weight: var(--tempra-weight-strong);\n  line-height: var(--tempra-leading-tight);\n  letter-spacing: -0.02em;\n  overflow-wrap: anywhere;\n}\n\n.view-meta {\n  margin: 0;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-meta);\n}\n\n/* Every event, filtered over what is loaded: says how much, over the table. */\n.events-scope {\n  margin-bottom: var(--tempra-space-2);\n}\n\n/* A library's description under its name on the home (TEMPRA-102, take 4). */\n.view-lede {\n  margin: var(--tempra-space-1) 0 0;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-reader);\n  line-height: var(--tempra-line-height);\n}\n\n/* A link beside a header or a section's heading: \"The full ledger\", \"All 5\", \"Activity\". */\n.view-aside {\n  margin-left: auto;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-meta);\n  white-space: nowrap;\n}\n\n.view-section-head {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: baseline;\n  gap: var(--tempra-space-1) var(--tempra-space-2);\n  margin-bottom: var(--tempra-space-2);\n}\n\n.view-section-title {\n  margin: 0;\n  font-size: var(--tempra-text-ui);\n  font-weight: var(--tempra-weight-strong);\n}\n\n.view-empty {\n  margin: 0;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-ui);\n}\n\n.view-more {\n  margin: var(--tempra-space-3) 0 0;\n}\n\n/* Filters: pills in a row that wraps. */\n.view-filters {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: var(--tempra-space-2);\n  margin-bottom: var(--tempra-space-4);\n  font-size: var(--tempra-text-meta);\n}\n\n.view-filters button,\n.view-filters select {\n  font-size: var(--tempra-text-meta);\n}\n\n/* A segmented control: buttons in one grey pill, the chosen one white. */\n.segmented {\n  display: flex;\n  gap: 2px;\n  min-width: 0;\n  margin: 0;\n  padding: 2px;\n  border: 0;\n  border-radius: var(--tempra-radius-pill);\n  background: var(--tempra-color-ground);\n}\n\n.segmented button {\n  border-color: transparent;\n  background: transparent;\n  color: var(--tempra-color-muted);\n}\n\n.segmented button[aria-pressed=\"true\"],\n.segmented button[aria-pressed=\"true\"]:hover:not(:disabled) {\n  border-color: var(--tempra-color-border);\n  background: var(--tempra-color-bg);\n  color: var(--tempra-color-text);\n}\n\n/* A choice as an outlined pill (a native select, so it works by keyboard and on a phone). */\n.pill-select {\n  border-color: var(--tempra-color-border);\n  border-radius: var(--tempra-radius-pill);\n  color: var(--tempra-color-muted);\n  cursor: pointer;\n}\n\n@media (max-width: 900px) {\n  .view-filters button,\n  .view-filters select {\n    min-height: var(--tempra-touch);\n  }\n\n  .segmented button {\n    min-height: calc(var(--tempra-touch) - 4px);\n  }\n}\n\n/* ---------- Home (take 4, TEMPRA-117) ---------- */\n\n.home-section {\n  margin-top: var(--tempra-space-4);\n}\n\n.home-who a,\n.home-since a {\n  color: var(--tempra-color-text);\n}\n\n/* Since you last looked (TEMPRA-121): one quiet line under the header's. */\n.home-since {\n  margin-top: var(--tempra-space-1);\n}\n\n/* A part of the home that could not load says so, quietly (H-7). */\n.home-failed {\n  color: var(--tempra-color-muted);\n}\n\n.home-failed button {\n  margin-left: var(--tempra-space-1);\n}\n\n/* Recently changed: a row per page, the title, then where, who and when. */\n.home-recent {\n  margin: 0;\n  padding: 0;\n  list-style: none;\n}\n\n.home-recent-row {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: baseline;\n  gap: 0 var(--tempra-space-3);\n  padding: var(--tempra-space-1) 0;\n}\n\n.home-recent-title {\n  min-width: 0;\n  color: var(--tempra-color-text);\n  font-weight: var(--tempra-weight-medium);\n  text-decoration: none;\n  overflow-wrap: anywhere;\n}\n\n.home-recent-title:hover {\n  text-decoration: underline;\n}\n\n.home-recent-meta {\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-meta);\n}\n\n/* For you here: up to three cards in a row, each one link. */\n.home-cards {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(12rem, 1fr));\n  gap: var(--tempra-space-2);\n  margin: 0;\n  padding: 0;\n  list-style: none;\n}\n\n.home-card {\n  display: flex;\n  flex-direction: column;\n  gap: var(--tempra-space-1);\n  height: 100%;\n  padding: var(--tempra-space-3);\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-card);\n  color: var(--tempra-color-text);\n  text-decoration: none;\n}\n\n.home-card:hover {\n  border-color: var(--tempra-color-border-strong);\n  background: var(--tempra-color-hover);\n}\n\n.home-card-kind {\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-meta);\n}\n\n.home-card-title {\n  font-weight: var(--tempra-weight-medium);\n  overflow-wrap: anywhere;\n}\n\n.home-card-detail {\n  overflow: hidden;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-ui);\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n/* Sections: rows, the name (and its description when folders carry one), the count and the dot. */\n.home-sections {\n  margin: 0;\n  padding: 0;\n  list-style: none;\n}\n\n.home-section-row {\n  display: flex;\n  align-items: center;\n  gap: var(--tempra-space-3);\n  min-height: var(--tempra-touch);\n  padding: var(--tempra-space-2) 0;\n  color: var(--tempra-color-text);\n  text-decoration: none;\n}\n\n.home-section-row:hover .home-section-name {\n  text-decoration: underline;\n}\n\n.home-section-name {\n  flex: 1;\n  min-width: 0;\n  font-weight: var(--tempra-weight-medium);\n  overflow-wrap: anywhere;\n}\n\n.home-section-end {\n  display: flex;\n  align-items: center;\n  gap: var(--tempra-space-2);\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-meta);\n  font-variant-numeric: tabular-nums;\n}\n\n/* The dot's place is kept when there is none, so the counts line up. */\n.home-section-dot {\n  display: inline-flex;\n  width: var(--tempra-dot);\n}\n\n/* The foot: the agents' housekeeping, quiet. */\n.home-foot {\n  margin: var(--tempra-space-4) 0 0;\n  font-size: var(--tempra-text-ui);\n}\n\n.home-foot a {\n  display: inline-flex;\n  align-items: center;\n  gap: var(--tempra-space-1);\n  color: var(--tempra-color-muted);\n  text-decoration: none;\n}\n\n.home-foot a:hover {\n  color: var(--tempra-color-text);\n}\n\n/* An empty library (board 31): one box with the steps and the waiting line, Import below. */\n.empty-library {\n  display: flex;\n  flex-direction: column;\n  gap: var(--tempra-space-3);\n  padding: var(--tempra-space-4);\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-card);\n}\n\n.empty-steps {\n  display: flex;\n  flex-direction: column;\n  gap: var(--tempra-space-3);\n  margin: 0;\n  padding: 0;\n  list-style: none;\n  counter-reset: step;\n}\n\n.empty-steps > li {\n  display: grid;\n  grid-template-columns: var(--tempra-avatar) minmax(0, 1fr);\n  gap: var(--tempra-space-2) var(--tempra-space-3);\n  align-items: baseline;\n  counter-increment: step;\n}\n\n.empty-steps > li::before {\n  content: counter(step);\n  display: grid;\n  place-items: center;\n  width: var(--tempra-avatar);\n  height: var(--tempra-avatar);\n  border: 1px solid var(--tempra-color-border-strong);\n  border-radius: 50%;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-meta);\n}\n\n.empty-steps > li > * {\n  grid-column: 2;\n}\n\n.empty-steps > li > :first-child {\n  grid-row: 1;\n}\n\n/* A value to copy: the mono on a grey ground, the copy button at its end. */\n.copy-field {\n  display: flex;\n  align-items: center;\n  gap: var(--tempra-space-2);\n  padding: var(--tempra-space-1) var(--tempra-space-1) var(--tempra-space-1) var(--tempra-space-3);\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-row);\n  background: var(--tempra-color-ground);\n}\n\n.copy-field code {\n  flex: 1;\n  min-width: 0;\n  overflow-wrap: anywhere;\n  background: none;\n  font-size: var(--tempra-text-ui);\n}\n\n.empty-wait {\n  display: flex;\n  align-items: center;\n  gap: var(--tempra-space-2);\n  margin: 0;\n  padding: var(--tempra-space-3);\n  border: 1px dashed var(--tempra-color-border-strong);\n  border-radius: var(--tempra-radius-row);\n  color: var(--tempra-color-muted);\n}\n\n.empty-more {\n  margin: var(--tempra-space-3) 0 0;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-ui);\n}\n\n@media (max-width: 900px) {\n  .empty-library {\n    padding: var(--tempra-space-3);\n  }\n}\n\n/* ---------- Activity ---------- */\n\n.activity-day {\n  display: flex;\n  flex-direction: column;\n  gap: var(--tempra-space-1);\n  margin-bottom: var(--tempra-space-4);\n}\n\n/* An entry: who, what they did, when; new ones carry the solid dot at the right (take 4). */\n.entry {\n  display: grid;\n  grid-template-columns: var(--tempra-avatar) minmax(0, 1fr) auto;\n  gap: 12px;\n  padding: 12px 10px;\n  border-radius: var(--tempra-radius-box);\n  font-size: var(--tempra-text-ui);\n}\n\n/* On Activity's Summary, entries are rows with hairlines between them, no fill. */\n.activity-day .entry {\n  border-bottom: 1px solid var(--tempra-color-border);\n  border-radius: 0;\n}\n\n/* Where the new entries end (TEMPRA-121): the label, then a rule under the last new entry. */\n.entry-divider {\n  margin: 0;\n  display: flex;\n  align-items: center;\n  gap: var(--tempra-space-2);\n  padding: var(--tempra-space-2) 10px 0;\n  border-bottom: 1px solid var(--tempra-color-border-strong);\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-meta);\n}\n\n.entry-divider > span {\n  display: inline-flex;\n  align-items: center;\n  gap: var(--tempra-space-2);\n  padding-bottom: var(--tempra-space-1);\n}\n\n.entry > .avatar-mark {\n  margin-top: 1px;\n}\n\n.entry-body {\n  display: flex;\n  flex-direction: column;\n  gap: var(--tempra-space-1);\n  min-width: 0;\n}\n\n.entry-line {\n  margin: 0;\n  font-size: var(--tempra-font-size);\n  overflow-wrap: anywhere;\n}\n\n.entry-words,\n.entry-more {\n  color: var(--tempra-color-muted);\n}\n\n.entry-words {\n  font-size: var(--tempra-text-meta);\n}\n\n/* The request's note, quoted. */\n.entry-note {\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-font-size);\n  overflow-wrap: anywhere;\n}\n\n/* The concepts it touched: what happened, the title, the words changed. */\n.entry-touched {\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n  margin: var(--tempra-space-1) 0 0;\n  padding: 0;\n  list-style: none;\n}\n\n.entry-touched li {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: baseline;\n  gap: 0 10px;\n  min-width: 0;\n}\n\n.entry-what {\n  flex: none;\n  width: 52px;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-label);\n}\n\n.entry-side {\n  display: flex;\n  flex-direction: column;\n  align-items: flex-end;\n  gap: var(--tempra-space-2);\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-meta);\n  white-space: nowrap;\n}\n\n/* Activity's controls (take 4, TEMPRA-115): the view switch and the filters, Download at the\n   right end of the row. */\n.activity-filters select {\n  max-width: 14rem;\n}\n\na.activity-download {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  margin-left: auto;\n  font-size: var(--tempra-text-meta);\n}\n\n/* The text filter: an outlined pill with a search glyph inside it. */\n.activity-find {\n  display: flex;\n  flex: 1 1 14rem;\n  align-items: center;\n  gap: 6px;\n  max-width: 24rem;\n  padding: 0 12px;\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-pill);\n  color: var(--tempra-color-muted);\n}\n\n.activity-find:focus-within {\n  outline: var(--tempra-focus-ring);\n  outline-offset: 1px;\n}\n\n.activity-find input:not([type=\"checkbox\"], [type=\"radio\"], [type=\"file\"]) {\n  flex: 1;\n  min-width: 0;\n  padding: 5px 0;\n  border: 0;\n  outline: 0;\n  background: none;\n  color: var(--tempra-color-text);\n  font-size: var(--tempra-text-meta);\n}\n\n/* The live entry: an agent writing now, the pulsing dot and \"now\" at the right. */\n.entry.live {\n  align-items: center;\n}\n\n.entry-now {\n  flex-direction: row;\n  align-items: center;\n  gap: 6px;\n}\n\n/* Every event: the ledger as a quiet table, hairlines between rows, the path in the mono. */\n.events-table {\n  width: 100%;\n  border-collapse: collapse;\n  font-size: var(--tempra-text-ui);\n}\n\n.events-table th {\n  padding: 8px 10px;\n  border-bottom: 1px solid var(--tempra-color-border);\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-meta);\n  font-weight: var(--tempra-weight-regular);\n  text-align: left;\n  white-space: nowrap;\n}\n\n.events-table td {\n  padding: 8px 10px;\n  border-bottom: 1px solid var(--tempra-color-border);\n  vertical-align: baseline;\n}\n\n.events-seq,\n.events-when,\n.events-kind {\n  color: var(--tempra-color-muted);\n  white-space: nowrap;\n}\n\n.events-seq {\n  font-family: var(--tempra-font-mono);\n  font-size: var(--tempra-text-meta);\n}\n\n/* The dot sits in the seq column's left gutter, so the numbers line up with or without it. */\n.events-seq .change-dot {\n  margin: 0 8px 0 -14px;\n}\n\n.events-table td.events-seq {\n  padding-left: 22px;\n}\n\n.events-person {\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n  white-space: nowrap;\n}\n\n.events-path {\n  overflow-wrap: anywhere;\n}\n\n.events-path a {\n  text-decoration: none;\n}\n\n.events-path a:hover code {\n  text-decoration: underline;\n}\n\n.events-path code {\n  font-size: var(--tempra-text-meta);\n  white-space: nowrap;\n}\n\n.events-note,\n.events-aside {\n  margin-left: 10px;\n  color: var(--tempra-color-muted);\n}\n\n.events-aside {\n  font-size: var(--tempra-text-meta);\n}\n\n@media (max-width: 900px) {\n  .entry {\n    gap: 10px;\n    padding: 12px 8px;\n  }\n}\n\n/* ---------- A folder (take 4, TEMPRA-117) ---------- */\n\n.folder {\n  display: flex;\n  flex-direction: column;\n  gap: var(--tempra-space-3);\n}\n\n.folder-empty,\n.folder-foot {\n  margin: 0;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-meta);\n}\n\n.folder-foot {\n  margin-top: var(--tempra-space-3);\n}\n\n.folder-foot a {\n  color: var(--tempra-color-muted);\n}\n\n/* Rows with no rules: subfolders first, then concepts, title over its description. */\n.folder-list {\n  display: flex;\n  flex-direction: column;\n  gap: var(--tempra-space-1);\n  margin: 0;\n  padding: 0;\n  list-style: none;\n}\n\n.folder-row {\n  display: flex;\n  align-items: flex-start;\n  gap: var(--tempra-space-3);\n  padding: var(--tempra-space-2) 0;\n  color: var(--tempra-color-text);\n  text-decoration: none;\n}\n\n.folder-row:hover .folder-title {\n  text-decoration: underline;\n}\n\n.folder-main {\n  display: flex;\n  flex: 1;\n  flex-direction: column;\n  min-width: 0;\n}\n\n.folder-title {\n  display: flex;\n  align-items: center;\n  gap: var(--tempra-space-2);\n  font-weight: var(--tempra-weight-medium);\n  overflow-wrap: anywhere;\n}\n\n.folder-sub {\n  align-items: center;\n}\n\n.folder-sub .folder-title {\n  flex: 1;\n  min-width: 0;\n}\n\n.folder-sub .folder-title svg,\n.folder-file .folder-title svg {\n  flex: none;\n  color: var(--tempra-color-muted);\n}\n\n.folder-desc {\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-ui);\n}\n\n.folder-count,\n.folder-live {\n  flex: none;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-meta);\n  white-space: nowrap;\n}\n\n.folder-dot {\n  display: inline-flex;\n  flex: none;\n}\n\n@media (max-width: 900px) {\n  .folder-live {\n    display: none;\n  }\n}\n\n/* ---------- An attachment (board 28) ---------- */\n\n/* The file large on a dark frame; beside it its name, actions and facts. */\n.attachment {\n  display: grid;\n  grid-template-columns: minmax(0, 1fr) minmax(14rem, 18rem);\n  gap: var(--tempra-space-4);\n  align-items: start;\n}\n\n.attachment > .notice {\n  grid-column: 1 / -1;\n}\n\n.attachment-frame {\n  display: grid;\n  place-items: center;\n  min-height: 24rem;\n  padding: var(--tempra-space-4);\n  border-radius: var(--tempra-radius-card);\n  background: var(--tempra-color-frame);\n  color: var(--tempra-color-frame-ink);\n}\n\n.attachment-frame img {\n  display: block;\n  max-width: 100%;\n  max-height: 70vh;\n  object-fit: contain;\n}\n\n.attachment-icon {\n  display: grid;\n  place-items: center;\n}\n\n.attachment-side {\n  display: flex;\n  flex-direction: column;\n  gap: var(--tempra-space-3);\n  min-width: 0;\n}\n\n.attachment-name {\n  margin: 0;\n  font-size: var(--tempra-text-h2);\n  font-weight: var(--tempra-weight-strong);\n  line-height: var(--tempra-leading-tight);\n  overflow-wrap: anywhere;\n}\n\n.attachment-actions {\n  display: flex;\n  flex-wrap: wrap;\n  gap: var(--tempra-space-2);\n  margin: 0;\n}\n\n.attachment-actions .button {\n  display: inline-flex;\n  align-items: center;\n  gap: var(--tempra-space-1);\n}\n\n/* Type, Size, Added, Used in: label and value in two columns between hairlines. */\n.attachment-facts {\n  margin: 0;\n  border-top: 1px solid var(--tempra-color-border);\n}\n\n.attachment-facts > div {\n  display: grid;\n  grid-template-columns: 5.5rem minmax(0, 1fr);\n  gap: var(--tempra-space-2);\n  padding: var(--tempra-space-2) 0;\n  border-bottom: 1px solid var(--tempra-color-border);\n}\n\n.attachment-facts dt {\n  color: var(--tempra-color-muted);\n}\n\n.attachment-facts dd {\n  margin: 0;\n  overflow-wrap: anywhere;\n}\n\n.attachment-used {\n  margin: 0;\n  padding: 0;\n  list-style: none;\n}\n\n@media (max-width: 1100px) {\n  .attachment {\n    grid-template-columns: minmax(0, 1fr);\n  }\n\n  .attachment-frame {\n    min-height: 14rem;\n    padding: var(--tempra-space-3);\n  }\n}\n\n/* ---------- Not found (board 32) ---------- */\n\n.not-found {\n  display: flex;\n  flex-direction: column;\n  gap: var(--tempra-space-3);\n}\n\n/* Where it went, in a box with Open at the end. */\n.not-found-fate {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: baseline;\n  justify-content: space-between;\n  gap: var(--tempra-space-2) var(--tempra-space-3);\n  margin: 0;\n  padding: var(--tempra-space-3);\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-card);\n  color: var(--tempra-color-muted);\n}\n\n.not-found-fate code {\n  color: var(--tempra-color-text);\n  overflow-wrap: anywhere;\n}\n\n.not-found-fate a {\n  color: var(--tempra-color-text);\n}\n\n.not-found-ways {\n  display: flex;\n  flex-wrap: wrap;\n  gap: var(--tempra-space-2);\n  margin: 0;\n}\n\n.not-found-ways button {\n  display: inline-flex;\n  align-items: center;\n  gap: var(--tempra-space-1);\n}\n\n/* ---------- The Inbox (take 4, boards 02 and 13; TEMPRA-116) ---------- */\n\n/*\n * One list, newest first, between hairline rules: an unread dot in the gutter, the library, kind\n * and time on a quiet line, the title, the detail line and a quote, and the row's actions on the\n * right. Lines and greys only.\n */\n\n.inbox-filters .inbox-mark {\n  margin-left: auto;\n  color: var(--tempra-color-muted);\n}\n\n.inbox-list {\n  margin: 0;\n  padding: 0;\n  border-top: 1px solid var(--tempra-color-border);\n  list-style: none;\n}\n\n.inbox-row {\n  display: grid;\n  grid-template-columns: var(--tempra-space-4) minmax(0, 1fr) auto;\n  align-items: start;\n  gap: 0 var(--tempra-space-2);\n  padding: var(--tempra-space-3) 0;\n  border-bottom: 1px solid var(--tempra-color-border);\n}\n\n.inbox-dot {\n  justify-self: center;\n  width: var(--tempra-dot);\n  height: var(--tempra-dot);\n  margin-top: calc(var(--tempra-text-meta) * 0.6);\n  border-radius: 50%;\n}\n\n.inbox-row.unread .inbox-dot {\n  background: var(--tempra-color-text);\n}\n\n.inbox-main {\n  display: flex;\n  flex-direction: column;\n  gap: var(--tempra-space-1);\n  min-width: 0;\n}\n\n.inbox-main p {\n  margin: 0;\n}\n\n.inbox-meta {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: var(--tempra-space-2);\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-meta);\n}\n\n.inbox-meta .lib-tile {\n  width: 18px;\n  height: 18px;\n  font-size: var(--tempra-text-label);\n}\n\n.inbox-title a {\n  color: var(--tempra-color-text);\n  font-weight: var(--tempra-weight-medium);\n  text-decoration: none;\n}\n\n.inbox-title a:hover {\n  text-decoration: underline;\n}\n\n.inbox-detail {\n  color: var(--tempra-color-muted);\n}\n\n.inbox-quote {\n  margin: var(--tempra-space-1) 0 0;\n  padding: 0 0 0 var(--tempra-space-3);\n  border-left: 2px solid var(--tempra-color-border);\n  color: var(--tempra-color-muted);\n}\n\n.inbox-actions {\n  display: flex;\n  flex-wrap: wrap;\n  justify-content: flex-end;\n  gap: var(--tempra-space-2);\n}\n\n@media (max-width: 900px) {\n  .inbox-row {\n    grid-template-columns: var(--tempra-space-4) minmax(0, 1fr);\n  }\n\n  .inbox-actions {\n    grid-column: 2;\n    justify-content: flex-start;\n    margin-top: var(--tempra-space-2);\n  }\n\n  .inbox-actions .button,\n  .inbox-actions button {\n    min-height: var(--tempra-touch);\n  }\n}\n\n/* ---------- An invitation (take 4, board 30; TEMPRA-135) ---------- */\n\n/* Who invited and when, the library as a card, the access offered, Accept and Decline. */\n.invitations {\n  display: flex;\n  flex-direction: column;\n  gap: var(--tempra-space-4);\n  margin: 0;\n  padding: 0;\n  list-style: none;\n}\n\n.invitation {\n  display: flex;\n  flex-direction: column;\n  gap: var(--tempra-space-3);\n  max-width: 32rem;\n}\n\n.invitation p {\n  margin: 0;\n}\n\n.invitation-from {\n  display: flex;\n  align-items: center;\n  gap: var(--tempra-space-2);\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-ui);\n}\n\n.invitation-card {\n  display: flex;\n  align-items: center;\n  gap: var(--tempra-space-3);\n  padding: var(--tempra-space-3);\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-box);\n}\n\n.invitation-card .lib-tile {\n  width: 36px;\n  height: 36px;\n}\n\n.invitation-library {\n  display: flex;\n  flex-direction: column;\n  min-width: 0;\n  overflow-wrap: anywhere;\n}\n\n.invitation-library span {\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-meta);\n}\n\n.invitation-access {\n  display: flex;\n  justify-content: space-between;\n  gap: var(--tempra-space-3);\n  font-size: var(--tempra-text-ui);\n}\n\n.invitation-access span {\n  color: var(--tempra-color-muted);\n}\n\n/*\n * The public pages (TEMPRA-110): the landing page (site/, tempra.dev) and the app's server pages\n * (sign-in, app consent, the email-change link, error pages). Take 3's look without the\n * workspace: the ground, the wordmark, the page as one sheet with a hairline edge, a quiet foot.\n * Nothing here needs a script.\n */\n\n/* The wordmark: the tile with the initial, as the sidebar's library switcher draws it, and the\n   name. */\n.wordmark {\n  display: inline-flex;\n  align-items: center;\n  gap: 10px;\n  color: var(--tempra-color-text);\n  font-size: var(--tempra-text-name);\n  font-weight: var(--tempra-weight-strong);\n  text-decoration: none;\n}\n\n.wordmark:visited,\n.wordmark:hover {\n  color: var(--tempra-color-text);\n}\n\n/* The frame: a column on the ground, the sheet in the middle of it. */\n.public {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  min-height: 100dvh;\n  padding: 0 16px var(--tempra-space-4);\n}\n\n.public-head,\n.public-foot,\n.public-sheet {\n  width: 100%;\n  max-width: var(--tempra-page-width);\n}\n\n.public-head {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  justify-content: space-between;\n  gap: 12px;\n  min-height: var(--tempra-bar);\n  padding: 8px 4px;\n}\n\n.public-nav {\n  display: flex;\n  align-items: center;\n  gap: 16px;\n  font-size: var(--tempra-text-ui);\n}\n\n.public-nav a:not(.button) {\n  color: var(--tempra-color-muted);\n  text-decoration: none;\n}\n\n.public-nav a:not(.button):hover {\n  color: var(--tempra-color-text);\n}\n\n.public-sheet {\n  padding: 48px var(--tempra-page-pad) 56px;\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-card);\n  background: var(--tempra-color-bg);\n}\n\n/* A form or a message (the server pages): a narrower column, the wordmark and foot with it. */\n.public.narrow .public-head,\n.public.narrow .public-foot,\n.public.narrow .public-sheet {\n  max-width: 560px;\n}\n\n.public-sheet > :first-child {\n  margin-top: 0;\n}\n\n.public-sheet > :last-child {\n  margin-bottom: 0;\n}\n\n.public-foot {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 4px 16px;\n  padding: 16px 4px;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-meta);\n}\n\n.public-foot a {\n  color: inherit;\n  text-decoration: none;\n}\n\n.public-foot a:hover {\n  color: var(--tempra-color-text);\n}\n\n/* ---------- The landing page ---------- */\n\n.public-sheet section + section {\n  margin-top: 56px;\n}\n\n.lede {\n  max-width: 34em;\n  margin: 12px 0 24px;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-reader);\n  line-height: var(--tempra-line-height);\n}\n\n.public-actions {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n}\n\n/* What Tempra does: short cards between hairlines, two to a row where there is room. */\n.features {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(min(100%, 16rem), 1fr));\n  gap: 10px;\n  margin: 16px 0 0;\n  padding: 0;\n  list-style: none;\n}\n\n.features li {\n  padding: 16px 18px;\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-box);\n}\n\n.features h3 {\n  margin: 0 0 4px;\n  font-size: var(--tempra-text-ui);\n  font-weight: var(--tempra-weight-strong);\n}\n\n.features p {\n  margin: 0;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-ui);\n  line-height: var(--tempra-line-height);\n}\n\n/* Steps: numbered in the faint grey, one to a line. */\n.steps {\n  margin: 16px 0 24px;\n  padding: 0;\n  list-style: none;\n  counter-reset: step;\n}\n\n.steps li {\n  display: flex;\n  gap: 12px;\n  padding: 10px 0;\n  border-top: 1px solid var(--tempra-color-border);\n  counter-increment: step;\n}\n\n.steps li:last-child {\n  border-bottom: 1px solid var(--tempra-color-border);\n}\n\n.steps li::before {\n  content: counter(step);\n  min-width: 1.25rem;\n  color: var(--tempra-color-muted);\n  font-variant-numeric: tabular-nums;\n}\n\n/* Terms and privacy: plain text at a comfortable measure. */\n.legal {\n  max-width: 38em;\n}\n\n.legal li + li {\n  margin-top: 8px;\n}\n\n@media (max-width: 640px) {\n  .public {\n    padding: 0 var(--tempra-gutter) var(--tempra-space-3);\n  }\n\n  .public-sheet {\n    padding: 28px 20px 36px;\n  }\n\n  .public-nav a:not(.button) {\n    display: inline-flex;\n    align-items: center;\n    min-height: var(--tempra-touch);\n  }\n}\n";

